local _, ns = ...

-- Boss abilities and strategy, keyed by creature (npc) ID, plus a short
-- overview per instance (AtlasLoot key). Generated; do not edit by hand.
--   npcs[npcID] = { abilities = { { spellID, name, school, tip, first, every }, ... }, strategy = "..." }
-- first and every: { min, max } seconds to the first cast and between casts, when known.
--   instances[key] = { overview = "..." }
-- Spell lists: the VMaNGOS Classic database (spell IDs only). Tips and
-- strategy: written for this addon. Names, icons and descriptions shown in
-- game come from the client by spell ID; the name here is only a fallback.
ns.BossData = {
    instances = {
        ["BlackfathomDeeps"] = { overview = "A level 24-32 flooded temple in Ashenvale held by naga and the Twilight's Hammer. Expect frost and nature casters, sleeps and roots, and lots of swimming between areas." },
        ["BlackrockDepths"] = { overview = "A huge Dark Iron dwarf city inside Blackrock Mountain for levels 52-60, packed with optional bosses, the Ring of Law arena, the Grim Guzzler tavern and Emperor Thaurissan at the end. Runs are long, so plan which wing you are doing and watch out for large patrols and fire-based casters." },
        ["BlackwingLair"] = { overview = "A level 60 40-player raid atop Blackrock Spire where Nefarian breeds chromatic dragons. Bring fire resistance and Onyxia Scale Cloaks, since several encounters revolve around Shadow Flame and heavy fire damage." },
        ["DireMaulEast"] = { overview = "The eastern wing of Dire Maul, for levels 55-60, is a corrupted grove of satyrs, imps and twisted plant life leading to Alzzin the Wildshaper. Expect heavy patrols and lots of shadow magic, so bring curse removal and interrupts." },
        ["DireMaulNorth"] = { overview = "The Gordok ogre wing of Dire Maul for levels 58-60, ending at King Gordok. Leave the guards alive and kill no Gordok on the way to earn a tribute run with extra loot and buffs." },
        ["DireMaulWest"] = { overview = "The Capital Gardens wing of Dire Maul for levels 58-60, home to Highborne spirits and demons. Destroy the pylons to free Immol'thar and expect heavy arcane and shadow casters." },
        ["Gnomeregan"] = { overview = "The irradiated gnome capital in Dun Morogh for levels 29-38, overrun by troggs, leper gnomes and malfunctioning machines. It is long and sprawling, so watch for wandering patrols and the poison clouds from oozes." },
        ["LowerBlackrockSpire"] = { overview = "Lower Blackrock Spire, for levels 55-60, is a long orc and ogre stronghold with many optional bosses spread across winding halls. Pulls are large and include casters, so careful crowd control and a sturdy tank go a long way." },
        ["Maraudon"] = { overview = "A sprawling level 46-55 cave system in Desolace split into purple and orange wings outside and a flooded inner area leading to Princess Theradras. Expect lots of plant, elemental and satyr packs, plus the five centaur Khan spirits roaming the outer wings." },
        ["MoltenCore"] = { overview = "A level 60 40-player raid in the fiery depths below Blackrock Mountain, ending with Ragnaros. Fire resistance helps throughout, and mages and druids should be ready to decurse on many fights." },
        ["Naxxramas"] = { overview = "A level 60 40-player raid in Kel'Thuzad's floating necropolis, split into four wings plus Frostwyrm Lair. It is the hardest Classic raid and needs strong gear, consumables and resistance sets for several bosses." },
        ["Onyxia"] = { overview = "A 40-player level 60 lair holding the black dragon Onyxia in a single three-phase encounter. Positioning around her breath, tail and fire is everything." },
        ["Ragefire"] = { overview = "A short level 13-18 Horde dungeon under Orgrimmar filled with troggs, cultists and fire elementals. Watch for casters using fire and curses, and pull carefully in the tight tunnels." },
        ["RazorfenDowns"] = { overview = "A quilboar burrow taken over by the Scourge in the southern Barrens, for levels 37-46. Expect undead and shadow casters, and a wave event at the gong before Tuten'kash." },
        ["RazorfenKraul"] = { overview = "A thorny quilboar warren in the southern Barrens for levels 29-38. Expect dense packs of quilboar casters and beasts, so crowd control and interrupts make life much easier." },
        ["ScarletMonasteryArmory"] = { overview = "The Armory wing of the Scarlet Monastery for levels 32-42, filled with hard-hitting Scarlet warriors. It ends with Herod, whose whirlwind punishes melee groups that stand too close." },
        ["ScarletMonasteryCathedral"] = { overview = "The Cathedral wing of the Scarlet Monastery for levels 35-45, home to the Crusade's leadership. The final fight pairs a paladin and a priest who can revive him, so plan your healing and crowd control." },
        ["ScarletMonasteryGraveyard"] = { overview = "The shortest Scarlet Monastery wing, for levels 26-36, filled with Scarlet Crusade defenders and restless undead. Fights are quick, but bring dispels for curses, fears and damage over time effects." },
        ["ScarletMonasteryLibrary"] = { overview = "The Library wing of the Scarlet Monastery, a short run for levels 29-39 through rooms full of Scarlet casters. Interrupt healers and keep pulls tight." },
        ["Scholomance"] = { overview = "A level 58-60 necromancy school beneath Caer Darrow, packed with undead students, dark casters and plenty of curses and shadow damage. Bring decursers and crowd control, and expect long pulls through the crypts and classrooms." },
        ["ShadowfangKeep"] = { overview = "A level 22-30 haunted castle in Silverpine full of worgen and undead. Expect shadow damage, curses and summoned adds, so having a decurse and a dispeller helps a lot." },
        ["Stratholme"] = { overview = "Stratholme, for levels 58-60, is split into the Scarlet-held Live side and the undead Scourge side, which ends with Baron Rivendare. Undead areas hit hard with curses, diseases and fear, so bring dispels and a fear answer." },
        ["TheDeadmines"] = { overview = "A level 17-26 Defias hideout below Moonbrook, ending on a pirate ship. Bosses hit hard in melee, and the final fight brings extra adds, so keep crowd control ready." },
        ["TheRuinsofAhnQiraj"] = { overview = "A level 60 20-player raid in the outer ruins of Ahn'Qiraj. It is a good stepping stone between Zul'Gurub and the larger raids, with several fights that punish poor movement." },
        ["TheStockade"] = { overview = "A compact level 24-32 prison in Stormwind packed with rioting inmates. Pulls are dense and adds join easily, so fight in corridors and control extra mobs." },
        ["TheTempleOfAtal'Hakkar"] = { overview = "A sunken troll temple in the Swamp of Sorrows for levels 50-60, with a statue puzzle, balcony troll minibosses, a pack of green dragonkin and the Avatar of Hakkar summoning event. Bring dispels for curses and magic, and watch for crowd control effects from the trolls." },
        ["TheTempleofAhnQiraj"] = { overview = "A level 60 40-player raid inside the Qiraji temple, culminating with the Old God C'Thun. Expect long trash packs, poison and nature damage, and fights that demand tight positioning and coordination." },
        ["Uldaman"] = { overview = "A titan excavation site in the Badlands for levels 41-51, crowded with Dark Iron dwarves, troggs and stone constructs. Many bosses are awakened guardians, so clear the room before starting them." },
        ["UpperBlackrockSpire"] = { overview = "Upper Blackrock Spire is a 10-player dungeon for level 60 groups, home to the Blackrock Horde and the black dragonflight. Expect big trash packs, an arena event with Rend Blackhand, and heavy fire damage throughout." },
        ["WailingCaverns"] = { overview = "A long level 17-24 cave system in the Barrens run by the Druids of the Fang. Many bosses cast Sleep and heal themselves, so bring interrupts and a dispeller, and expect a lot of walking." },
        ["WorldBosses"] = { overview = "Level 60 bosses found in the open world that need a full raid to defeat. Other players can interfere, so organize quickly and clear nearby mobs before pulling." },
        ["Zul'Farrak"] = { overview = "A sandfury troll city in Tanaris for levels 44-54. Watch for big pulls of trolls and the stair event, where the group must hold a choke point against waves of attackers." },
        ["Zul'Gurub"] = { overview = "A 20-player level 60 troll raid where the Hakkari priests must fall before the Blood God himself. Many bosses switch into animal forms, so watch for phase changes and keep a varied raid with cleansers." },
    },
    npcs = {
        [639] = { abilities = { { 5200, "VanCleef's Allies", 1, "Control or kill the adds" }, { 3391, "Thrash", 1, "Healer watches tank health", { 8, 12 }, { 15, 20 } } }, strategy = "VanCleef calls in his allies when his health gets low, so be ready to crowd control or kill them. Clear his guards before engaging. The tank holds him through Thrash bursts while DPS push him down fast." },
        [642] = { abilities = { { 7399, "Terrify", 32, "Tank regains threat after fear", { 9, 14 }, { 15, 21 } }, { 3603, "Distracting Pain", 1, nil, { 8, 12 }, { 48, 54 } }, { 5141, "Eject Sneed", 1, "Pick up Sneed after it dies" } }, strategy = "Kill the Shredder first; when it dies, Sneed is ejected and must be fought. The Shredder fears nearby players, so be ready to reestablish threat. Clear the goblins around the lumber area before pulling." },
        [643] = { abilities = { { 6713, "Disarm", 1, "Tank uses defensives while disarmed", { 7, 17 }, { 15, 20 } } }, strategy = "Sneed pops out after his Shredder dies and disarms the tank. Keep him on the tank and use defensive cooldowns while disarmed. He is fragile, so DPS can finish him quickly." },
        [644] = { abilities = { { 6304, "Rhahk'Zor Slam", 1, "Healer watches tank health", { 1, 8 }, { 17, 27 } } }, strategy = "Rhahk'Zor is a simple melee ogre who slams the tank. Clear the room first, then the tank holds him while DPS burn him. Keep the tank healed through the slams." },
        [645] = { abilities = { { 5174, "Cookie's Cooking", 2, "Interrupt the heal" }, { 6306, "Acid Splash", 8, "Healer watches group health", { 5, 5 }, { 27, 36 } } }, strategy = "Cookie heals himself with his cooking, so interrupt it when you can. Acid Splash adds nature damage to the fight. Kill the nearby pirates first, then burn him." },
        [646] = { abilities = { { 6432, "Smite Stomp", 1, "Prepare for the stun" }, { 3391, "Thrash", 1, "Expect bursts of extra hits" }, { 6435, "Smite Slam", 1, "Healer watches tank health" }, { 6264, "Nimble Reflexes", 1, "Expect more parries in melee" } }, strategy = "Mr. Smite stuns everyone with a stomp at health breakpoints, then switches weapons and hits harder. Clear the deck crew first because they will join him. The healer should keep the tank high before each stomp, and DPS should keep steady pressure." },
        [647] = { abilities = { { 5208, "Poisoned Harpoon", 8, "Cure poison on the target", { 6, 13 }, { 37, 97 } }, { 5532, "Cleave", 1, "Melee stand behind him", { 5, 18 }, { 17, 42 } } }, strategy = "Greenskin fights alongside his crew on the ship, so crowd control or kill the adds first. Melee stay behind him to avoid Cleave. Cure the poison from his harpoon when possible." },
        [1666] = { abilities = { { 8242, "Shield Slam", 1, "Healer watches tank health" } }, strategy = "Kam Deepfury fights like a defensive warrior and hits with Shield Slam. He is slow to kill, so keep steady DPS on him. The healer should be ready for Shield Slam spikes on the tank." },
        [1696] = { abilities = { { 8599, "Enrage", 1, "Burn him fast when enraged" }, { 3391, "Thrash", 1, "Expect bursts of extra hits", { 8, 12 }, { 15, 20 } } }, strategy = "Targorr hits the tank with extra attacks and enrages at low health. Clear nearby prisoners before pulling. The healer stays on the tank and DPS push him through the enrage quickly." },
        [1716] = { abilities = { { 7964, "Smoke Bomb", 1, "Expect a short stun", { 8, 10 }, { 15, 25 } }, { 9128, "Battle Shout", 1, "Kill him before buffs stack", { 8, 10 }, { 26, 30 } } }, strategy = "Bazil uses Smoke Bomb to stun players and Battle Shout to boost himself. Fight him away from other inmates so adds do not join. Keep the tank healed through the stuns and burn him quickly." },
        [1717] = { abilities = { { 421, "Chain Lightning", 8, "Interrupt this", { 5, 8 }, { 12, 19 } } }, strategy = "Hamhock casts Chain Lightning that jumps between players. Interrupt it and spread out to reduce the damage. The tank holds him while DPS focus him down." },
        [1720] = { abilities = {  }, strategy = "Bruegal is a rare elite with no special abilities listed. The tank holds him while DPS burn him down. Clear the surrounding inmates first." },
        [1763] = { abilities = { { 5213, "Molten Metal", 4, "Healer watches tank burn damage", { 2, 4 }, { 23, 44 } } }, strategy = "Gilnid hits the tank with Molten Metal, so the healer needs to watch that fire damage. Clear the goblins in the foundry first so they do not join. DPS burns him while the tank holds him in place." },
        [1853] = { abilities = { { 17950, "Shadow Portal", 1, "Regroup and kill the room adds" }, { 18702, "Curse of the Darkmaster", 1, "Stay with the group", { 15, 27 }, { 15, 27 } }, { 15790, "Arcane Missiles", 64, "Interrupt or heal through", { 4, 5 }, { 6, 20 } }, { 12040, "Shadow Shield", 32, "Burn through or dispel", { 12, 20 }, { 14, 28 } } }, strategy = "Gandling teleports players into side rooms that lock shut and fill with undead. Ported players must kill the adds to escape and return to the fight. Tank him in the center and keep healers ready for arcane missiles. Burn through his shadow shield." },
        [2748] = { abilities = {  }, strategy = "Archaedas wakes up and calls stone and earthen guardians throughout the fight. Have the tank hold him in the center while area damage clears the adds. Keep healers protected and burn him before too many guardians build up." },
        [3586] = { abilities = { { 12097, "Pierce Armor", 1, "Healer expects more tank damage", { 1, 7 }, { 34, 56 } } }, strategy = "Miner Johnson is a rare elite who lowers the tank's armor with Pierce Armor. The healer should expect the tank to take more damage once the debuff lands. Kill him quickly; he has nothing else to watch for." },
        [3653] = { abilities = {  }, strategy = "Kresh is a large turtle with no special abilities listed. The tank picks him up and the group burns him down in a simple tank-and-spank fight. Watch for nearby mobs in the water while fighting." },
        [3654] = { abilities = { { 8150, "Thundercrack", 8, "Healer stays ready after stuns", { 8, 10 }, { 10, 12 } }, { 7399, "Terrify", 32, "Tank regains threat after fear", { 10, 15 }, { 12, 18 } }, { 7967, "Naralex's Nightmare", 32, "Dispel the sleep quickly", { 8, 12 }, { 18, 25 } } }, strategy = "Mutanus appears after the Naralex event and uses a stun, a fear and a sleep. Keep dispels ready for Naralex's Nightmare and expect the tank to lose threat after fears. Healers should keep everyone topped up between stuns while DPS go all out." },
        [3669] = { abilities = { { 8040, "Druid's Slumber", 32, "Dispel sleep or interrupt the cast", { 10, 10 }, { 13, 20 } }, { 9532, "Lightning Bolt", 8, "Interrupt this", nil, { 2, 2 } }, { 7965, "Cobrahn Serpent Form", 1, "Expect harder melee hits" } }, strategy = "Cobrahn casts Sleep and Lightning Bolt, so keep interrupts ready and dispel sleeping players. Later in the fight he turns into a serpent and fights in melee, so the healer should focus the tank then. Kill him quickly once he transforms." },
        [3670] = { abilities = { { 5187, "Healing Touch", 8, "Interrupt the heal", nil, { 20, 25 } }, { 700, "Sleep", 32, "Dispel sleep on allies", { 8, 12 }, { 12, 20 } }, { 8147, "Thunderclap", 8, "Ranged stay out of melee range", { 6, 8 }, { 6, 11 } }, { 9532, "Lightning Bolt", 8, "Interrupt when heal is covered", nil, { 2, 2 } } }, strategy = "Pythas heals himself, so prioritize interrupting Healing Touch. Dispel Sleep and keep ranged players out of his Thunderclap range. The healer should be ready for spikes on the tank from bolts and Thunderclap." },
        [3671] = { abilities = { { 5187, "Healing Touch", 8, "Interrupt the heal", { 9, 14 }, { 15, 26 } }, { 700, "Sleep", 32, "Dispel sleep on allies", { 8, 12 }, { 12, 25 } }, { 9532, "Lightning Bolt", 8, "Interrupt when heal is covered", nil, { 2, 2 } }, { 8148, "Thorns Aura", 8, "Melee watch reflected damage", { 1, 1 }, { 50, 50 } } }, strategy = "Anacondra heals herself, so save interrupts for Healing Touch above all else. Dispel Sleep from players and keep the tank healed through Lightning Bolt. Melee should watch their health due to Thorns Aura." },
        [3673] = { abilities = { { 6778, "Healing Touch", 8, "Interrupt the heal", nil, { 120, 120 } }, { 700, "Sleep", 32, "Dispel sleep on allies", { 3, 6 }, { 10, 20 } }, { 9532, "Lightning Bolt", 8, "Interrupt when heal is covered", nil, { 2, 2 } } }, strategy = "Serpentis is another self-healing druid, so assign interrupts on Healing Touch. Dispel Sleep quickly to keep the tank and healer active. Burn him while his heals are locked out." },
        [3674] = { abilities = { { 6254, "Chained Bolt", 8, "Spread out to reduce chain damage" } }, strategy = "Skum is a thunder lizard that zaps several targets in a row. Spread the group apart so Chained Bolt jumps to fewer players. The tank holds him in place while DPS burn him." },
        [3865] = { abilities = { { 7139, "Fel Stomp", 32, "Ranged keep their distance", { 3, 16 }, { 16, 35 } } }, strategy = "These mounts are fought in the courtyard and stomp nearby enemies. The tank keeps them in place while DPS focus one at a time. Keep ranged at a distance to avoid the stomp." },
        [3872] = { abilities = { { 15584, "Cleave", 1, "Melee stand behind him", { 4, 5 }, { 8, 18 } }, { 9080, "Hamstring", 1, nil, { 6, 7 }, { 14, 33 } } }, strategy = "The Deathsworn Captain is a rare warrior elite. The tank faces him away from the group to avoid Cleave, and Hamstring will slow his target. Kill him with steady DPS while the healer covers the tank." },
        [3886] = { abilities = { { 7485, "Butcher Drain", 32, "Healer keeps tank topped up" } }, strategy = "Razorclaw drains life from the tank with Butcher Drain while hitting hard in melee. Clear the kitchen first. The healer stays focused on the tank while DPS burn him." },
        [3887] = { abilities = { { 7068, "Veil of Shadow", 32, "Remove the curse from the tank", { 1, 1 }, { 22, 35 } } }, strategy = "Silverlaine places Veil of Shadow on the tank, which cuts healing taken. Decurse it as soon as it lands. Otherwise he is a straightforward tank-and-spank fight." },
        [3914] = { abilities = { { 7295, "Soul Drain", 32, "Healer watches drained players", { 1, 14 }, { 14, 36 } } }, strategy = "Rethilgore drains health from his target with Soul Drain. The tank holds him while DPS kill him quickly. The healer should keep the drained player topped up." },
        [3927] = { abilities = { { 7489, "Call Lupine Horror", 32, "Kill or control the adds" }, { 7488, "Call Slavering Worg", 32, "Kill or control the adds" }, { 7487, "Call Bleak Worg", 32, "Kill or control the adds" } }, strategy = "Nandos calls in worgs to help him during the fight. The tank should pick up the adds as they arrive while DPS kill them or crowd control them. Once the adds are handled, finish off Nandos." },
        [3974] = { abilities = { { 17164, "Summon Scarlet Hound", 32, "AoE or off-tank the hounds" } }, strategy = "Loksey calls in Scarlet hounds once the fight starts. Have the tank collect the dogs and kill them quickly with area damage, then focus Loksey." },
        [3975] = { abilities = {  }, strategy = "Herod is a hard-hitting warrior who periodically spins and hits everyone near him. Melee should back off during the spin while the tank holds him. When he dies a wave of trainees rushes in, so be ready to use area damage at the door." },
        [3976] = { abilities = { { 5589, "Hammer of Justice", 2, "Heal through the stun", { 7, 16 }, { 60, 80 } }, { 1020, "Divine Shield", 2, "Wait out the bubble" }, { 14518, "Crusader Strike", 1, "Heal the tank", { 6, 12 }, { 6, 18 } }, { 8990, "Retribution Aura", 2, "Melee expect holy damage" } }, strategy = "Mograine is a paladin who stuns and hits hard. The tank holds him in the middle of the room while DPS burn him. When he falls, Whitemane enters, so save mana and cooldowns for the next phase." },
        [3977] = { abilities = { { 9256, "Deep Sleep", 32, "Have cooldowns ready after sleep" }, { 9232, "Scarlet Resurrection", 1, "Expect Mograine back, refocus him" }, { 14515, "Dominate Mind", 32, "Crowd control charmed allies", { 15, 30 }, { 60, 60 } }, { 12039, "Heal", 2, "Interrupt this", { 30, 60 }, { 30, 60 } }, { 22187, "Power Word: Shield", 2, "Dispel or burn through it", { 10, 30 }, { 10, 30 } }, { 9481, "Holy Smite", 2, "Interrupt when possible", { 0, 2 }, { 2, 3 } } }, strategy = "Whitemane attacks after Mograine dies and later puts everyone to sleep and revives him. When the group wakes, both bosses are up, so kill Mograine again quickly, then Whitemane. Interrupt her heals and handle mind control with stuns or crowd control." },
        [3983] = { abilities = { { 2767, "Shadow Word: Pain", 32, "Dispel the damage over time" } }, strategy = "Vishas uses Shadow Word: Pain on players. Dispel it and keep steady DPS on him. He is a simple fight otherwise." },
        [4274] = { abilities = { { 7125, "Toxic Saliva", 8, "Cure poison on the tank", { 2, 7 }, { 23, 49 } } }, strategy = "Fenrus poisons his target with Toxic Saliva. Cure the poison off the tank when you can. He is otherwise a simple melee fight." },
        [4275] = { abilities = { { 7621, "Arugal's Curse", 32, "Remove the curse quickly", { 10, 15 }, { 15, 20 } }, { 7588, "Void Bolt", 32, "Healer watches the target", nil, { 1, 1 } }, { 7803, "Thundershock", 8, "Spread out from each other", { 15, 15 }, { 15, 15 } }, { 7136, "Shadow Port", 32, "Chase him to his new spot" } }, strategy = "Arugal curses players, which can turn them against the group, so remove it quickly. He teleports around the room with Shadow Port, so the group must follow him. Spread out to limit Thundershock and heal through Void Bolt." },
        [4278] = { abilities = { { 1026, "Holy Light", 2, "Interrupt the heal", nil, { 12, 22 } }, { 498, "Divine Protection", 2, "Wait out the shield" } }, strategy = "Springvale is a paladin who heals himself and reduces damage with Divine Protection. Keep interrupts on Holy Light. When his shield is up, hold big cooldowns and resume when it fades." },
        [4279] = { abilities = { { 7481, "Howling Rage", 32, "Healer prepares for extra damage" } }, strategy = "Odo enrages with Howling Rage and hits much harder. Use tank cooldowns and focus healing when he enrages. DPS should burn him quickly to limit the enraged time." },
        [4420] = { abilities = { { 15548, "Thunderclap", 8, "Melee expect slowed attacks" }, { 9128, "Battle Shout", 1, "Kill adds before they buff", { 1, 3 }, { 30, 45 } } }, strategy = "Ramtusk is a warrior who uses Thunderclap to hit and slow everyone in melee range. Pull him away from nearby quilboar so the fight stays small. Tank him, keep heals on the tank, and have ranged deal most of the damage." },
        [4421] = { abilities = { { 8292, "Chain Bolt", 8, "Spread out to limit bounces", nil, { 2, 4 } }, { 8358, "Mana Spike", 2, "Mana users stay out of range" }, { 6077, "Renew", 2, "Dispel or purge the heal", { 0, 5 }, { 15, 21 } }, { 8361, "Purity", 2, "Interrupt or dispel her buffs", { 9, 13 }, { 9, 15 } } }, strategy = "Charlga is a caster who heals herself and her guards and throws a bouncing Chain Bolt. Kill or crowd control her adds first. Interrupt her heals, spread out to reduce Chain Bolt damage, and keep the tank topped up." },
        [4422] = { abilities = { { 8260, "Rushing Charge", 1, "Healers stay out of charge path" }, { 8285, "Rampage", 1, "Heal the tank through it", { 8, 14 }, { 25, 31 } }, { 8269, "Enrage", 1, "Burn him fast when enraged" }, { 8555, "Left for Dead", 1, "Heal hit players right away" } }, strategy = "Agathelos is a large boar who charges and hits hard. The tank should keep him faced away from the group while healers stay at range. Save cooldowns for when he enrages at low health and finish him quickly." },
        [4424] = { abilities = { { 14900, "Chain Heal", 8, "Interrupt this" }, { 8286, "Summon Boar Spirit", 1, "Kill the boar spirit quickly", { 9, 15 }, { 30, 45 } }, { 6192, "Battle Shout", 1, "Tank pulls him away from adds", { 1, 3 }, { 40, 60 } } }, strategy = "Aggem is a quilboar shaman who heals with Chain Heal and calls a boar spirit to help. Keep a melee interrupter on Chain Heal. Clear his nearby adds first so his heals have fewer targets, then burn him down." },
        [4425] = { abilities = {  }, strategy = "Blind Hunter is a rare bat that may or may not be present. Tank and spank it, keeping the group together so the tank holds aggro." },
        [4428] = { abilities = { { 14515, "Dominate Mind", 32, "Crowd control charmed allies, do not kill", { 7, 10 }, { 10, 15 } }, { 9613, "Shadow Bolt", 32, "Interrupt this", nil, { 2, 2 } } }, strategy = "Jargba is a caster who throws Shadow Bolts and mind controls party members. Interrupt his bolts and focus him down fast. If someone is charmed, stun or slow them rather than damaging them, and keep healing the tank." },
        [4438] = { abilities = { { 8259, "Whirling Barrage", 1, "Melee step back during the spin", { 4, 7 }, { 7, 11 } }, { 8148, "Thorns Aura", 8, "Expect damage when hitting him", { 1, 3 }, { 60, 70 } } }, strategy = "Spearhide spins to hit everyone around him and is surrounded by a thorns aura. Keep healers ready for the spin damage on melee. Ranged damage is safest, and melee should watch their health." },
        [4542] = { abilities = { { 12096, "Fear", 32, "Use fear wards or tremor" }, { 8282, "Curse of Blood", 32, "Remove the curse" }, { 8399, "Sleep", 32, "Dispel sleep" }, { 12039, "Heal", 2, "Interrupt this" }, { 11647, "Power Word: Shield", 2, "Dispel the shield" }, { 15090, "Dispel Magic", 2, "Reapply your buffs" } }, strategy = "Fairbanks is an optional priest boss who fears, sleeps and heals himself. Interrupt his heals and dispel his shield. Remove curses and sleeps from your group to keep the damage flowing." },
        [4543] = { abilities = { { 12470, "Fire Nova", 4, "Ranged stay out of nova range", { 0, 9 }, { 9, 12 } }, { 8053, "Flame Shock", 4, "Dispel or heal through", { 0, 16 }, { 16, 60 } }, { 8814, "Flame Spike", 4, "Interrupt this", { 0, 8 }, { 8, 16 } }, { 9613, "Shadow Bolt", 32, "Interrupt this", { 0, 3 }, { 3, 5 } } }, strategy = "Thalnos is a fire and shadow caster. Interrupt his bolts and spikes, and ranged should stay out of Fire Nova range. The healer covers burn damage while the group focuses him down." },
        [4829] = { abilities = { { 3815, "Poison Cloud", 8, "Move out of the cloud", { 5, 9 }, { 5, 9 } }, { 3490, "Frenzied Rage", 1, "Burn him fast when enraged" } }, strategy = "Aku'mai drops Poison Cloud and frenzies during the fight. Move out of poison clouds and keep the tank healed. Save cooldowns for when he enrages." },
        [4830] = { abilities = {  }, strategy = "Old Serra'kis is fought underwater, so watch your breath bar. No special abilities are listed. The tank holds him while DPS burn him fast." },
        [4831] = { abilities = { { 8435, "Forked Lightning", 8, "Tank faces her away", nil, { 1, 3 } }, { 865, "Frost Nova", 16, "Melee get out after nova", { 6, 9 }, { 9, 13 } }, { 246, "Slow", 8, "Dispel the slow", { 7, 9 }, { 9, 13 } } }, strategy = "Sarevess is a naga caster with frost and lightning spells. Tank her facing away from the group to limit Forked Lightning. Dispel Slow and expect brief roots from Frost Nova; clear her guards first." },
        [4832] = { abilities = { { 8399, "Sleep", 32, "Dispel sleep on allies" }, { 15587, "Mind Blast", 32, "Interrupt this", { 2, 5 }, { 7, 9 } } }, strategy = "Kelris puts players to sleep and hits with Mind Blast. Dispel Sleep quickly, especially on the healer and tank. Interrupt Mind Blast to reduce damage." },
        [4842] = { abilities = { { 8270, "Summon Earth Rumbler", 1, "Off-tank or kill the rumbler" }, { 2484, "Earthbind Totem", 8, "Destroy the totem", { 0, 2 }, { 50, 60 } }, { 9532, "Lightning Bolt", 8, "Interrupt this", nil, { 2, 2 } } }, strategy = "Halmgar calls an Earth Rumbler elemental and drops a slowing totem. Kill the totem quickly and pick up the add with an off-tank or burn it down. Interrupt his Lightning Bolts while the tank holds him." },
        [4854] = { abilities = { { 11892, "Shrink", 1, "Dispel or wait it out", { 18, 25 }, { 25, 35 } }, { 8292, "Chain Bolt", 8, "Spread out to limit bounces", { 8, 12 }, { 21, 31 } }, { 9532, "Lightning Bolt", 8, "Interrupt this", nil, { 2, 2 } }, { 8143, "Tremor Totem", 8, "Kill the totem", { 5, 7 }, { 120, 130 } } }, strategy = "Grimlok is a trogg caster who shrinks players and casts lightning. Kill his adds first, then interrupt his bolts. Spread out to limit Chain Bolt damage." },
        [4887] = { abilities = { { 5568, "Trample", 1, "Melee watch health", { 5, 8 }, { 9, 13 } } }, strategy = "Ghamoo-ra is a big turtle with heavy armor that tramples nearby enemies. Casters do the most damage here. The tank holds him and the healer covers melee from Trample." },
        [5708] = { abilities = { { 12280, "Acid of Hakkar", 8, "Cure the poison", { 1, 3 }, { 1, 6 } } }, strategy = "Spawn of Hakkar is a winged serpent that the tank should pick up and hold steady. DPS kill it while healers cure the poison from Acid of Hakkar. This is a short fight with steady damage." },
        [5709] = { abilities = { { 12890, "Deep Slumber", 32, "Heal through or dispel the sleep", { 5, 6 }, { 20, 25 } }, { 11876, "War Stomp", 1, "Melee may be stunned" }, { 3391, "Thrash", 1, "Heal the tank through bursts", { 1, 1 }, { 1, 1 } } }, strategy = "The Shade of Eranikus is the last boss of the temple and has extra adds nearby that should be cleared first. The tank holds him in place while DPS burns him down. Deep Slumber puts players to sleep, so healers should keep everyone topped up before it lands and dispel it where possible." },
        [5710] = { abilities = { { 12479, "Hex of Jammal'an", 32, "CC or dispel hexed players" }, { 12468, "Flamestrike", 4, "Move out of the fire", { 10, 15 }, { 10, 15 } }, { 12492, "Healing Wave", 8, "Interrupt the heal", nil, { 3, 10 } }, { 8376, "Earthgrab Totem", 1, "Destroy the totem", { 8, 15 }, { 8, 15 } } }, strategy = "Jammal'an fights together with Ogom, so kill Jammal'an first while the off-tank or a CC holds Ogom. Interrupt his Healing Wave and move out of Flamestrike immediately. Hexed players turn on the group, so crowd control them until it wears off." },
        [5711] = { abilities = { { 12493, "Curse of Weakness", 32, "Remove the curse", { 54, 55 }, { 20, 26 } }, { 11639, "Shadow Word: Pain", 32, "Dispel the damage over time", { 9, 15 }, { 38, 58 } }, { 12471, "Shadow Bolt", 32, "Interrupt the shadow bolts", nil, { 2, 2 } } }, strategy = "Ogom is usually fought right after Jammal'an. Keep him in melee and interrupt his Shadow Bolts. Decurse the tank and dispel Shadow Word: Pain to keep healing manageable." },
        [5716] = { abilities = { { 9081, "Shadow Bolt Volley", 32, "Interrupt the volley", { 10, 12 }, { 10, 12 } }, { 12058, "Chain Lightning", 8, "Spread out, interrupt it", { 2, 3 }, { 6, 10 } }, { 12492, "Healing Wave", 8, "Interrupt the heals" }, { 11899, "Healing Ward", 1, "Destroy the healing ward", { 6, 8 }, { 15, 20 } }, { 12279, "Curse of Blood", 32, "Remove the curse", { 4, 6 }, { 8, 10 } }, { 12790, "Hukku's Guardians", 32, "Kill the summoned guardians", { 8, 10 }, { 15, 18 } }, { 12530, "Frailty", 32, "Dispel the magic debuff", { 8, 10 }, { 14, 16 } }, { 12506, "Atal'ai Skeleton Totem", 1, "Kill the totem fast", { 8, 10 }, { 10, 12 } } }, strategy = "The balcony holds six troll minibosses, and they must all die to open the way to Jammal'an. Pull them one at a time and keep the rest of the balcony packs clear. Interrupt their heals and volleys, kill any totems or wards they drop, and dispel curses and magic debuffs as they land." },
        [5719] = { abilities = { { 12884, "Acid Breath", 8, "Tank faces it away", { 2, 6 }, { 8, 17 } }, { 12882, "Wing Flap", 8, "Tank backs against a wall", { 8, 13 }, { 19, 34 } } }, strategy = "Morphaz is one of the green dragonkin and often appears together with Hazzas. Face him away from the group and keep the tank against a wall to avoid knockbacks. DPS attack from the sides and stay clear of his breath." },
        [5720] = { abilities = { { 12884, "Acid Breath", 8, "Tank faces it away", { 2, 6 }, { 6, 21 } }, { 12882, "Wing Flap", 8, "Tank backs against a wall", { 8, 13 }, { 19, 34 } } }, strategy = "Weaver is one of the green dragonkin in the temple. The tank faces it away from the group with their back to a wall to limit knockbacks. DPS attack from the sides and stay out of the breath." },
        [5721] = { abilities = { { 12884, "Acid Breath", 8, "Tank faces it away", { 2, 6 }, { 8, 17 } }, { 12882, "Wing Flap", 8, "Tank backs against a wall", { 8, 13 }, { 19, 34 } } }, strategy = "Dreamscythe is one of the green dragonkin in the temple. The tank faces it away from the group and stands with their back to a wall so Wing Flap does not knock them around. DPS attack from the sides and stay out of the breath." },
        [5722] = { abilities = { { 12884, "Acid Breath", 8, "Tank faces it away", { 2, 6 }, { 8, 17 } }, { 12882, "Wing Flap", 8, "Tank backs against a wall", { 8, 13 }, { 19, 34 } } }, strategy = "Hazzas is one of the green dragonkin and often appears together with Morphaz. If both come at once, use two tanks or burn one quickly. Face each dragon away from the group, keep tanks against walls, and avoid standing in front of them." },
        [5775] = { abilities = {  }, strategy = "No special abilities are listed for Verdan. The tank holds him in place while the group focuses him down. The healer should stay ready for heavy melee damage on the tank." },
        [5912] = { abilities = {  }, strategy = "This rare elite has no abilities listed here. Pick it up with the tank and burn it down. Clear nearby mobs first so the fight stays clean." },
        [6109] = { abilities = { { 21147, "Arcane Vacuum", 64, "Tank threat resets, let tank rebuild", { 20, 20 }, { 30, 45 } }, { 21097, "Manastorm", 16, "Move out of the storm", { 16, 16 }, { 11, 22 } }, { 21099, "Frost Breath", 16, "Tank faces it away from raid", { 12, 12 }, { 10, 20 } }, { 22067, "Reflection", 1, "Casters stop casting during reflect", { 21, 21 }, { 20, 35 } }, { 21098, "Chill", 16, "Dispel the slow", { 14, 14 }, { 22, 29 } }, { 19983, "Cleave", 1, "Only the tank in front", { 7, 7 }, { 7, 7 } } }, strategy = "Azuregos pulls everyone near him with Arcane Vacuum and wipes threat, so DPS hold back after each pull. Keep him facing away for Frost Breath and move out of Manastorm. Casters stop when his reflect shield is up." },
        [6168] = { abilities = { { 8270, "Summon Earth Rumbler", 1, "Pick up the elemental add" }, { 9532, "Lightning Bolt", 8, "Interrupt this", nil, { 2, 4 } } }, strategy = "Roogug is a geomancer who summons an earth elemental and casts Lightning Bolt. Have the tank grab the elemental while DPS focuses Roogug. Interrupt his bolts to keep damage low." },
        [6228] = { abilities = { { 10870, "Summon Burning Servant", 4, "Kill the fire servant first" }, { 9053, "Fireball", 4, "Interrupt this", { 1, 2 }, { 2, 2 } }, { 184, "Fire Shield II", 4, "Melee expect fire damage", { 1, 1 }, { 60, 65 } } }, strategy = "The Dark Iron Ambassador is a fire caster who summons a burning servant. Kill or control the servant, then interrupt the Ambassador's Fireballs. His fire shield hurts melee, so heal them through it." },
        [6229] = { abilities = { { 10887, "Crowd Pummel", 1, "Melee spread or stay back" }, { 8374, "Arcing Smash", 1, "Only the tank in front", { 11, 13 }, { 8, 18 } }, { 5568, "Trample", 1, "Melee watch health", { 9, 22 }, { 16, 33 } } }, strategy = "Crowd Pummeler hits everyone around it with frequent area attacks. Keep the group out of its front and limit how many melee are stacked on it. Heal through the area damage and burn it quickly." },
        [6231] = { abilities = { { 10855, "Lag", 8, "Expect slows, keep moving", { 4, 8 }, { 15, 25 } }, { 10852, "Battle Net", 1, "Root expected, stay close", { 5, 5 }, { 19, 19 } }, { 10858, "Summon Dupe Bug", 1, "Kill the bug adds", { 10, 10 }, { 22, 22 } }, { 10860, "Patch", 1, "Interrupt this", { 20, 30 }, { 30, 60 } } }, strategy = "Techbot is an easy optional robot near the start. It roots and slows players and spawns small bug copies. Kill the bugs as they appear and burn the boss down." },
        [6235] = { abilities = { { 11085, "Chain Bolt", 8, "Spread out to limit bounces", { 17, 33 }, { 17, 38 } }, { 11082, "Megavolt", 8, "Heal through the burst" }, { 15605, "Shock", 8, "Heal the tank", { 15, 26 }, { 10, 27 } } }, strategy = "Electrocutioner 6000 deals heavy nature damage with bouncing bolts and a shock attack. Nature resistance helps a lot. Spread the group to reduce Chain Bolt bounces and keep healing steady." },
        [6243] = { abilities = { { 12024, "Net", 1, "Ranged keep attacking while netted" } }, strategy = "Gelihast nets players in place, so melee may get stuck briefly. Clear the murlocs around him first. The tank holds him while ranged keep up the pressure." },
        [6487] = { abilities = { { 9438, "Arcane Bubble", 2, "Run away when he bubbles" }, { 9435, "Detonation", 4, "Get out of range now" }, { 13323, "Polymorph", 1, "Dispel polymorph" }, { 8988, "Silence", 8, "Casters keep distance" }, { 9433, "Arcane Explosion", 64, "Melee step out of range" } }, strategy = "Doan is an arcane caster who polymorphs and silences. Partway through he shields himself and charges a big explosion, so everyone must run out of range immediately. Return once it goes off and finish him." },
        [6488] = { abilities = { { 7160, "Execute", 1, "Keep the tank's health high" }, { 15496, "Cleave", 1, "Melee stand behind him" } }, strategy = "The Fallen Champion is a warrior-type rare who cleaves and executes low health targets. Keep the tank healthy to avoid Execute and face him away from the group. DPS him down steadily." },
        [6489] = { abilities = { { 3815, "Poison Cloud", 8, "Move out of the cloud", { 6, 9 }, { 20, 36 } }, { 21007, "Curse of Weakness", 32, "Remove the curse from the tank", { 5, 8 }, { 19, 35 } } }, strategy = "Ironspine drops poison clouds and curses the tank. Move out of the clouds and decurse the tank. Otherwise he is a straightforward melee fight." },
        [6490] = { abilities = { { 5137, "Call of the Grave", 32, "Remove the curse quickly", { 10, 10 }, { 15, 15 } }, { 7399, "Terrify", 32, "Tank regains threat after fear", { 20, 20 }, { 20, 20 } }, { 9373, "Soul Siphon", 32, "Healer watches drained players" } }, strategy = "Azshir curses players, fears the group and drains health. Remove the curse and be ready to recover threat after fears. Burn him quickly to limit the drains." },
        [6906] = { abilities = { { 14516, "Strike", 1, "Heal the tank", { 4, 7 }, { 9, 13 } }, { 15620, "Shoot", 1, "Pull him into melee range", nil, { 2, 4 } } }, strategy = "Baelog is one of the three Vikings and shoots from range. Pull him in with line of sight or have a ranged player keep him busy. Kill the Vikings one by one." },
        [6907] = { abilities = { { 6268, "Rushing Charge", 1, "Healers stay near the tank" } }, strategy = "Eric is one of three Lost Vikings fought together. He charges around the room, so have an off-tank or crowd control on him. Kill the Vikings one at a time while the tank holds the others." },
        [6908] = { abilities = { { 8242, "Shield Slam", 1, "Heal the tank" } }, strategy = "Olaf is the shield-bearing Viking who hits the tank hard. Assign a tank to hold him while the group kills the others first, then finish him." },
        [6910] = { abilities = { { 16006, "Chain Lightning", 8, "Spread out and interrupt", { 8, 13 }, { 18, 25 } }, { 15801, "Lightning Bolt", 8, "Interrupt this", nil, { 2, 2 } } }, strategy = "Revelosh is a trogg caster with nature damage spells. Clear his adds first, then interrupt his lightning casts. Spread out to reduce Chain Lightning damage." },
        [7023] = { abilities = { { 10061, "Summon Obsidian Shard", 1, "Kill the shards quickly" }, { 10072, "Splintered Obsidian", 1, "Expect shards from damage" } }, strategy = "The Obsidian Sentinel splits off obsidian shards as it takes damage. Use area damage to clear the shards as they spawn while the tank keeps the Sentinel. Avoid leaving many shards alive at once." },
        [7079] = { abilities = { { 21687, "Toxic Volley", 8, "Cure poison on the group", { 5, 8 }, { 11, 14 } } }, strategy = "Viscous Fallout is a large ooze that casts a nature-damage poison volley on everyone nearby. Have poison cures ready and heal through the group damage. Tank it and burn it down." },
        [7206] = { abilities = { { 10132, "Sand Storms", 1, "Avoid the sand storms", { 4, 7 }, { 30, 45 } } }, strategy = "The Ancient Stone Keeper creates moving sand storms. Keep away from the storms and burn the Keeper down while the tank holds it in place." },
        [7228] = { abilities = {  }, strategy = "Ironaya is a stone keeper who knocks back and stomps. Clear the room first, then tank her against a wall so knockbacks do not scatter the group. Melee should watch for her stomp damage." },
        [7267] = { abilities = { { 11837, "Wide Slash", 1, "Only the tank in front", { 12, 16 }, { 7, 24 } }, { 15623, "Cleave", 1, "Only the tank in front", { 6, 20 }, { 8, 19 } }, { 8269, "Enrage", 1, "Burn him fast" } }, strategy = "Ukorz is the final troll chief and fights with Ruuzlu. Keep Ukorz faced away from the group because he cleaves. Tank both, focus Ukorz, and use cooldowns when he enrages." },
        [7271] = { abilities = { { 11086, "Ward of Zum'rah", 1, "Destroy the ward", { 7, 20 }, { 15, 32 } }, { 15245, "Shadow Bolt Volley", 32, "Heal the group", { 6, 30 }, { 10, 18 } }, { 12491, "Healing Wave", 8, "Interrupt this", { 10, 15 }, { 15, 23 } }, { 12739, "Shadow Bolt", 32, "Interrupt this", { 1, 1 }, { 3, 5 } } }, strategy = "Zum'rah raises zombies from the graves and summons a ward that creates more. Destroy the ward and pick up the undead adds. Interrupt his heals and bolts while the group focuses him." },
        [7272] = { abilities = { { 8600, "Fevered Plague", 8, "Cure the disease", { 15, 18 }, { 10, 22 } } }, strategy = "Theka turns into a beetle and casts a disease on players. Cure the plague and keep healing steady. Tank and burn him down." },
        [7273] = { abilities = { { 11836, "Freeze Solid", 16, "Heal frozen players", { 5, 15 }, { 5, 15 } }, { 11902, "Gahz'rilla Slam", 1, "Stay away during slam", { 3, 10 }, { 3, 10 } }, { 11131, "Icicle", 16, "Spread out", { 7, 20 }, { 7, 20 } } }, strategy = "Gahz'rilla is a hydra summoned by striking the gong. It freezes players and slams the area around it. Spread out, keep healing steady, and burn it down." },
        [7274] = { abilities = { { 15623, "Cleave", 1, "Only the tank in front", { 7, 13 }, { 7, 23 } }, { 7160, "Execute", 1, "Keep the tank healthy" } }, strategy = "The Sandfury Executioner holds the key needed to free the prisoners. Keep him faced away from the group because he cleaves. Keep the tank healthy to avoid Execute." },
        [7275] = { abilities = { { 13704, "Psychic Scream", 32, "Use fear wards or tremor", { 11, 16 }, { 22, 32 } }, { 12039, "Heal", 2, "Interrupt this", nil, { 14, 25 } }, { 8362, "Renew", 2, "Dispel the heal", nil, { 28, 35 } }, { 15537, "Shadow Bolt", 32, "Interrupt this", nil, { 2, 4 } } }, strategy = "Sezz'ziz is a shadow priest who fears and heals. He is fought during the stair event, so control the trolls first. Interrupt his heals and remove his Renew." },
        [7291] = { abilities = { { 11969, "Fire Nova", 4, "Melee step back", { 17, 18 }, { 8, 14 } }, { 8053, "Flame Shock", 4, "Heal the target", { 9, 12 }, { 9, 16 } }, { 9482, "Amplify Flames", 4, "Fire resistance helps" }, { 3356, "Flame Lash", 4, "Heal through the damage", { 13, 14 }, { 11, 22 } } }, strategy = "Galgann is a fire-casting dwarf with nova and shock attacks. Melee should back off when he novas, and fire resistance helps. Clear his room first and keep healers out of nova range." },
        [7354] = { abilities = { { 7645, "Dominate Mind", 32, "Crowd control charmed allies", { 9, 13 }, { 15, 20 } }, { 12039, "Heal", 2, "Interrupt this", nil, { 12, 16 } }, { 12471, "Shadow Bolt", 32, "Interrupt this", nil, { 2, 2 } }, { 11639, "Shadow Word: Pain", 32, "Dispel the DoT", { 3, 5 }, { 20, 25 } } }, strategy = "Ragglesnout is a rare caster who heals himself and mind controls players. Interrupt his heals and bolts and dispel Shadow Word: Pain. Handle any charmed player with stuns rather than damage." },
        [7355] = { abilities = { { 12255, "Curse of Tuten'kash", 32, "Remove the curse", { 9, 14 }, { 15, 25 } }, { 12252, "Web Spray", 1, "Stunned briefly, heal through", { 3, 5 }, { 6, 8 } } }, strategy = "Tuten'kash appears after the gong waves. He webs the group and curses players. Remove curses quickly and keep the tank healed through the webs." },
        [7356] = { abilities = { { 12946, "Putrid Stench", 1, "Heal the affected players", { 8, 12 }, { 15, 23 } } }, strategy = "Plaguemaw is a rare boar that puts out a putrid stench. Tank it and burn it down while healers keep everyone topped up." },
        [7357] = { abilities = { { 12470, "Fire Nova", 4, "Melee step back", { 8, 12 }, { 11, 16 } }, { 12466, "Fireball", 4, "Interrupt this", nil, { 2, 2 } } }, strategy = "Mordresh is a fire caster who novas players around him. Interrupt his Fireballs and keep melee ready to step back from the nova. Fire resistance helps." },
        [7358] = { abilities = { { 12642, "Summon Frost Spectres", 1, "AoE or off-tank the spectres" }, { 13009, "Amnennar's Wrath", 1, "Heal the group", { 8, 8 }, { 12, 12 } }, { 15531, "Frost Nova", 16, "Melee break free", { 10, 15 }, { 10, 15 } }, { 15530, "Frostbolt", 16, "Interrupt this", nil, { 2, 6 } } }, strategy = "Amnennar is a lich who pulses frost damage on the group and summons frost spectres. Kill the spectres as they appear with area damage or an off-tank. Healers should focus on steady group healing." },
        [7361] = { abilities = {  }, strategy = "Grubbis appears during the gate event with his pet Chomper. Hold the choke point, have the tank pick up both, kill Chomper or Grubbis while healers watch the tank, and keep troggs off the healer." },
        [7604] = { abilities = { { 8858, "Bomb", 4, "Spread out" }, { 21688, "Goblin Land Mine", 1, "Avoid the mines" }, { 11972, "Shield Bash", 1, "Healers stay at range" }, { 12170, "Revenge", 1, "Heal the tank" }, { 6660, "Shoot", 1, "Pull into melee" } }, strategy = "Sergeant Bly is a prisoner freed during the stair event who later turns on the group with his crew. Tank Bly, crowd control or off-tank his allies, and kill the casters first. Watch for bombs and mines." },
        [7795] = { abilities = { { 12491, "Healing Wave", 8, "Interrupt this", nil, { 9, 22 } }, { 15245, "Shadow Bolt Volley", 32, "Heal the group", { 5, 10 }, { 17, 22 } }, { 12739, "Shadow Bolt", 32, "Interrupt this", nil, { 2, 2 } }, { 11086, "Ward of Zum'rah", 1, "Destroy the ward", { 2, 5 }, { 13, 28 } } }, strategy = "Velratha is a caster who heals herself and casts shadow bolts. Interrupt her heals and burn her quickly. Destroy any wards she drops." },
        [7800] = { abilities = { { 11504, "Walking Bomb Effect", 1, "Kill bombs before they reach you" }, { 11795, "Activate Bomb B", 1, "Close the nearby bomb faces" }, { 10101, "Knock Away", 1, "Tank avoid knocking into bombs" } }, strategy = "Thermaplugg activates bomb faces around his room that release walking bombs. Assign one or two players to kill or block bombs while the tank holds him away from them. His Knock Away resets threat, so the tank should rebuild quickly." },
        [8127] = { abilities = { { 11894, "Antu'sul's Minion", 32, "AoE down the basilisks" }, { 11899, "Healing Ward", 1, "Destroy the healing ward" }, { 11314, "Fire Nova Totem", 4, "Destroy the totem fast", { 7, 11 }, { 10, 13 } }, { 8376, "Earthgrab Totem", 1, "Break free from roots" }, { 10413, "Earth Shock", 8, "Interrupt or heal through", { 7, 7 }, { 7, 7 } }, { 11895, "Healing Wave of Antu'sul", 2, "Interrupt this" } }, strategy = "Antu'sul fights on a hill with lots of basilisk adds and drops totems and wards. Kill totems and wards immediately, and use area damage on the basilisks. Interrupt his heals and focus him when the adds are under control." },
        [8443] = { abilities = { { 12888, "Cause Insanity", 32, "CC the mind-controlled player", { 9, 10 }, { 9, 10 } }, { 6607, "Lash", 1, "Tank gets knocked around", { 9, 18 }, { 9, 18 } } }, strategy = "The Avatar is summoned through an event in the central room, so clear the area and be ready for adds while setting it up. Once he is up, the tank holds him while DPS burns him down. When Cause Insanity takes over a player, crowd control them rather than killing them, and keep the tank healed through Lash." },
        [8567] = { abilities = { { 12795, "Enrage", 1, "Burn fast at low health" } }, strategy = "Glutton is a straightforward melee boss that enrages at low health. Have the tank hold him and save damage cooldowns for the enrage so the tank takes as little burst as possible." },
        [8580] = { abilities = { { 6524, "Ground Tremor", 1, "Melee may be stunned, heal through", { 9, 18 }, { 20, 32 } } }, strategy = "Atal'alarion is summoned by activating the statues in the right order. The tank holds him in place while DPS work on him. Healers should keep the tank topped up, since short stuns can interrupt the group." },
        [8696] = { abilities = {  }, strategy = "Henry Stern is a friendly NPC who teaches recipes, not a fight. Talk to him in the cell to learn his tea and gold-blood recipes." },
        [8923] = { abilities = {  }, strategy = "Panzor is a rare golem with no abilities listed here. The tank holds him while DPS burns him down. Treat it as a simple tank and spank and keep the tank healed." },
        [8929] = { abilities = { { 15586, "Heal", 2, "Interrupt the heal" }, { 10929, "Renew", 2, "Dispel her renew" }, { 10901, "Power Word: Shield", 2, "Dispel or burn the shield" }, { 15587, "Mind Blast", 32, "Interrupt the mind blast" }, { 15654, "Shadow Word: Pain", 32, "Dispel the damage over time" }, { 10934, "Smite", 2 } }, strategy = "Moira stands beside the Emperor and heals him, which can drag the fight out badly. Interrupt her heals and dispel her buffs, or crowd control her while the group kills Thaurissan. Note that killing her affects some quest outcomes, so decide on your plan before the pull." },
        [8983] = { abilities = { { 15305, "Chain Lightning", 8, "Spread out, interrupt it", { 14, 14 }, { 15, 15 } }, { 15605, "Shock", 8, "Heal through the shock", { 6, 6 }, { 7, 7 } }, { 15507, "Lightning Shield", 8, "Melee watch shield damage" } }, strategy = "Argelmach is a golem lord who can bring nearby golems into the fight, so clear his area first. The tank holds him while DPS burns him down. Spread out to limit Chain Lightning, and melee should note Lightning Shield damage." },
        [9016] = { abilities = { { 23379, "Magma Splash", 4, "Heal through the fire splash", { 8, 12 }, { 10, 14 } } }, strategy = "Bael'Gar is a large fire elemental. The tank holds him in place while DPS burns him down. Healers should expect steady fire damage on the tank, and fire resistance helps." },
        [9017] = { abilities = { { 26977, "Curse of the Elemental Lord", 4, "Remove the curse", { 1, 5 }, { 20, 28 } }, { 13899, "Fire Storm", 4, "Move out of the fire", { 12, 16 }, { 11, 14 } }, { 13900, "Fiery Burst", 4, "Heal through the fire burst", { 6, 11 }, { 9, 16 } }, { 14099, "Mighty Blow", 1, "Tank backs against a wall", { 9, 17 }, { 18, 24 } } }, strategy = "Lord Incendius is a fire lord at the Black Anvil. The tank keeps their back to a wall so Mighty Blow does not knock them away. Decurse his curse quickly, move out of Fire Storm, and use fire resistance if you have it." },
        [9018] = { abilities = { { 13704, "Psychic Scream", 32, "Fear ward or tremor the tank" }, { 14033, "Mana Burn", 32, "Healers stay out of range" }, { 14032, "Shadow Word: Pain", 32, "Dispel the damage over time" }, { 12040, "Shadow Shield", 32, "Dispel or burn the shield" } }, strategy = "Gerstahn is a shadow priest who burns mana and fears the group. Keep her in melee and use fear protection if you have it. Healers and casters should try to stay at range, dispel Shadow Word: Pain, and purge or burn through her shield." },
        [9019] = { abilities = { { 17492, "Hand of Thaurissan", 4, "Heal the stunned target" }, { 15636, "Avatar of Flame", 4, "Melee step out, stay spread" } }, strategy = "The Emperor is the final boss and is backed by Moira, who heals him. Deal with Moira first by interrupting or controlling her. The tank holds Thaurissan while ranged players stay spread, and healers watch for big fire damage from Avatar of Flame and Hand of Thaurissan." },
        [9024] = { abilities = { { 15095, "Molten Blast", 4, "Interrupt the blast", { 4, 6 }, { 7, 11 } }, { 15616, "Flame Shock", 4, "Dispel the fire damage over time", { 6, 11 }, { 12, 19 } }, { 15038, "Scorching Totem", 4, "Kill the totem fast", { 7, 10 }, { 25, 35 } }, { 15041, "Fire Ward", 4, "Use non-fire damage", { 2, 7 }, { 30, 45 } } }, strategy = "Loregrain is a fire caster. Keep him in melee and interrupt Molten Blast. Destroy his Scorching Totem as soon as it drops, and fire casters should swap to other schools while his Fire Ward is up." },
        [9025] = { abilities = { { 13729, "Flame Shock", 4, "Dispel the fire damage over time", { 5, 8 }, { 13, 18 } }, { 13728, "Earth Shock", 8, "Interrupts casters, heal through", { 7, 11 }, { 9, 14 } }, { 6524, "Ground Tremor", 1, "Melee may be stunned" } }, strategy = "Lord Roccor is a fire and earth elemental shaman type. The tank holds him in place while DPS burns him down. Healers should dispel Flame Shock and keep in mind that Earth Shock can lock out their spells briefly." },
        [9027] = { abilities = {  }, strategy = "Gorosh is one of the possible Ring of Law bosses and has no abilities listed here. The tank holds him in the center while DPS burns him down. Stay close enough together to be healed, and kill any arena adds first if they become a problem." },
        [9028] = { abilities = {  }, strategy = "Grizzle is one of the possible Ring of Law bosses and has no abilities listed here. Treat it as a straight tank and spank, with the tank holding him and DPS focusing him. Healers keep the tank topped up." },
        [9029] = { abilities = { { 15245, "Shadow Bolt Volley", 32, "Interrupt the volley", { 6, 9 }, { 12, 16 } }, { 14331, "Vicious Rend", 1, "Heal the tank through bleeds", { 4, 8 }, { 5, 10 } }, { 7121, "Anti-Magic Shield", 32, "Casters switch to melee or wait", { 15, 20 }, { 15, 25 } } }, strategy = "Eviscerator mixes melee bleeds with a shadow volley. Interrupt the volley whenever you can and heal the tank through Vicious Rend. When the anti-magic shield goes up, casters should pause or switch targets while melee keep attacking." },
        [9030] = { abilities = { { 13323, "Polymorph", 1, "Dispel polymorphed players", { 12, 18 }, { 15, 20 } }, { 13747, "Slow", 64, "Dispel the slow", { 15, 25 }, { 15, 25 } }, { 15453, "Arcane Explosion", 64, "Melee step back from it", { 6, 9 }, { 6, 12 } }, { 15254, "Arcane Bolt", 64, "Interrupt the arcane bolts", { 5, 9 }, { 5, 9 } } }, strategy = "Ok'thor is an arcane caster in the Ring of Law. The tank keeps him in melee while DPS interrupt his casts. Dispel polymorph and slow quickly, and melee should step away when Arcane Explosion is coming." },
        [9031] = { abilities = {  }, strategy = "Anub'shiah is one of the possible Ring of Law bosses and has no abilities listed here. The tank holds him while DPS focus him down. Be ready to switch to any summoned adds and dispel debuffs as they appear." },
        [9032] = { abilities = { { 15474, "Web Explosion", 1, "Expect a brief web stun", { 17, 22 }, { 17, 22 } }, { 15475, "Baneful Poison", 8, "Cure the poison", { 7, 12 }, { 8, 15 } }, { 3609, "Paralyzing Poison", 1, "Cure the paralysis poison", { 10, 15 }, { 14, 20 } } }, strategy = "Hedrum is a large spider that poisons and webs the group. The tank holds him while DPS burns him down. Cure poisons quickly, especially Paralyzing Poison, and be ready for healing during web stuns." },
        [9033] = { abilities = { { 15572, "Sunder Armor", 1, "Healers watch the tank's armor drop" } }, strategy = "General Angerforge is a strong melee boss who calls reinforcements when he gets low. Clear the room first, then tank him in a spot where adds are easy to pick up. Save DPS cooldowns for the final stretch and kill or off-tank the reinforcements." },
        [9034] = { abilities = { { 15245, "Shadow Bolt Volley", 32, "Interrupt the volley" }, { 15585, "Prayer of Healing", 2, "Interrupt the group heal", { 15, 20 }, { 15, 20 } }, { 15586, "Heal", 2, "Interrupt the heal", nil, { 16, 20 } }, { 14033, "Mana Burn", 32, "Healers stay out of range", { 14, 17 }, { 15, 20 } }, { 15092, "Summon Voidwalkers", 1, "Kill or CC the voidwalkers" }, { 12674, "Frost Nova", 16, "Expect roots near the mage", { 12, 16 }, { 20, 23 } }, { 13737, "Mortal Strike", 1, "Heal the tank through it", { 9, 13 }, { 14, 18 } }, { 12540, "Gouge", 1, "Tank regains threat after gouge", { 8, 12 }, { 12, 17 } } }, strategy = "The Seven are a series of dwarf spirits who attack one after another, each with a different class style. Fight them in a clear area and focus each one down as it activates. Interrupt heals and volleys, kill or control summoned voidwalkers, and keep the tank healed through melee spirits." },
        [9041] = { abilities = { { 12674, "Frost Nova", 16, "Melee expect roots, stay near", { 7, 9 }, { 14, 18 } }, { 12675, "Frostbolt", 16, "Interrupt the frostbolts", nil, { 2, 2 } }, { 15044, "Frost Ward", 16, "Use non-frost damage", { 3, 4 }, { 65, 70 } }, { 12544, "Frost Armor", 16 } }, strategy = "Stilgiss fights alongside his hound Verek. The tank keeps Stilgiss in melee, and someone should handle Verek. Interrupt Frostbolt, and frost casters should switch schools while his Frost Ward is up." },
        [9042] = { abilities = { { 8599, "Enrage", 1, "Burn him fast at low health" }, { 15042, "Curse of Blood", 32, "Remove the curse" } }, strategy = "Verek is Warder Stilgiss's hound and enrages as he gets low. Off-tank him while the group works on Stilgiss, or kill him first. Decurse Curse of Blood and use cooldowns when he enrages." },
        [9056] = { abilities = { { 15493, "Holy Light", 2, "Interrupt the heal" }, { 13953, "Holy Strike", 2, "Heal the tank" }, { 11978, "Kick", 1, "Casters expect interrupts", nil, { 11, 15 } }, { 15346, "Seal of Reckoning", 2 } }, strategy = "Fineous is a paladin type who heals himself. Interrupt every Holy Light cast so the fight does not drag out. The tank holds him while DPS burns him down, and healers keep the tank topped up through Holy Strike." },
        [9156] = { abilities = { { 14744, "Burning Spirit", 1, "Kill the spirits before they reach him" } }, strategy = "Ambassador Flamelash is helped by burning spirits that move toward him and empower him. The tank holds Flamelash while ranged DPS kill the spirits before they reach him. Burn the boss once the spirits are under control." },
        [9196] = { abilities = { { 24375, "War Stomp", 1, "Melee expect brief stuns" }, { 20686, "Knock Away", 1, "Tank stays near a wall" }, { 24317, "Sunder Armor", 1, "Healers watch tank armor loss" }, { 18106, "Rend", 1, "Healers keep up with bleed" }, { 22356, "Slow", 64, "Dispel the slow" } }, strategy = "Clear the surrounding ogres first, since Omokk has many guards nearby. Tank him with his back to a wall so Knock Away does not send the tank into new packs. Healers keep the tank topped through Sunder Armor and Rend." },
        [9217] = { abilities = { { 13323, "Polymorph", 1, "Dispel polymorph from allies", { 7, 12 }, { 14, 19 } }, { 15230, "Arcane Bolt", 64, "Interrupt this", nil, { 2, 3 } }, { 8365, "Enlarge", 1, "Purge the buff if possible", nil, { 25, 30 } } }, strategy = "A rare ogre caster who polymorphs players and buffs his allies. Interrupt his Arcane Bolts and dispel polymorph quickly. Kill him before his escort." },
        [9218] = { abilities = {  }, strategy = "A rare ogre elite that relies on melee damage. Tank him in place and burn him down while healers focus the tank." },
        [9219] = { abilities = {  }, strategy = "A rare ogre elite with straightforward melee damage. Tank and burn him while healers focus the tank." },
        [9236] = { abilities = { { 16708, "Hex", 8, "Dispel hex quickly" }, { 24673, "Curse of Blood", 32, "Remove the curse quickly" }, { 20691, "Cleave", 1, "Only the tank stands in front" } }, strategy = "Clear her troll guards before engaging. Tank her facing away from the group so Cleave only hits the tank. Dispel Hex and remove Curse of Blood to keep the fight under control." },
        [9237] = { abilities = {  }, strategy = "Voone is a heavy-hitting melee troll. Clear his room first, tank him away from casters, and keep healers focused on the tank and any melee taking splash damage." },
        [9319] = { abilities = {  }, strategy = "Grebmar is fought with his hounds nearby, so pull carefully and handle the dogs first or with an off-tank. The tank keeps Grebmar in place while DPS focus the adds, then the boss. Keep healers out of large pulls to avoid being swarmed." },
        [9438] = { abilities = { { 12738, "Amplify Damage", 32, "Dispel the damage amplify", { 3, 5 }, { 15, 20 } }, { 14875, "Curse of Agony", 32, "Remove the curse", { 5, 7 }, { 12, 18 } }, { 15232, "Shadow Bolt", 32, "Interrupt the shadow bolts", nil, { 2, 2 } }, { 15228, "Fireball", 4, "Interrupt the fireballs", nil, { 2, 2 } }, { 12675, "Frostbolt", 16, "Interrupt the frostbolts", nil, { 2, 2 } }, { 15234, "Lightning Bolt", 8, "Interrupt the lightning bolts", nil, { 2, 2 } }, { 7121, "Anti-Magic Shield", 32, "Casters switch to melee or wait", { 7, 12 }, { 18, 24 } }, { 17139, "Power Word: Shield", 2, "Dispel the shield", { 9, 14 }, { 40, 55 } } }, strategy = "This entry covers the caster enemies tied to the Dark Coffer, who use a wide mix of spell schools. Assign interrupts, kill them one at a time, and dispel shields and debuffs as they appear. Healers should stay out of line of sight of casters where possible." },
        [9476] = { abilities = {  }, strategy = "Watchman Doomgrip guards the vault and has no clearly listed abilities here. The tank holds him while DPS burns him down. Kill or control any guards that join the fight before turning to Doomgrip." },
        [9502] = { abilities = { { 15588, "Thunderclap", 8, "Melee expect to be slowed" }, { 15285, "Fireball Volley", 4, "Spread out and heal through" }, { 14099, "Mighty Blow", 1, "Tank backs against a wall" } }, strategy = "Phalanx is a big golem who guards the Grim Guzzler. The tank keeps their back to a wall so Mighty Blow does not knock them far. Healers should prepare for group fire damage from Fireball Volley, and melee should expect Thunderclap slows." },
        [9537] = { abilities = { { 9573, "Flame Breath", 4, "Tank faces it away", { 5, 20 }, { 10, 20 } }, { 14872, "Drunken Rage", 1, "Burn him or use cooldowns" } }, strategy = "This fight takes place in the Grim Guzzler and can come with extra drunk adds. Face the boss away from the group to avoid Flame Breath. Handle adds with an off-tank or crowd control, and be ready for harder hits when he becomes enraged." },
        [9568] = { abilities = { { 11130, "Knock Away", 1, "Tank stays near a wall" }, { 20691, "Cleave", 1, "Only the tank stands in front" }, { 23511, "Demoralizing Shout", 1, "Healers watch the tank" } }, strategy = "Clear his room so any guards that join can be handled. Tank Wyrmthalak with his back to a wall and facing away from the group. Expect reinforcements during the fight and have an offtank or crowd control ready." },
        [9596] = { abilities = { { 13737, "Mortal Strike", 1, "Healers keep the tank topped", nil, { 7, 11 } } }, strategy = "Bannok is a rare elite who hits hard and reduces healing on the tank. Tank him away from nearby packs and burn him quickly. Healers should keep the tank high through Mortal Strike windows." },
        [9718] = { abilities = {  }, strategy = "A rare ogre elite with standard melee attacks. Tank him in place and burn him down." },
        [9736] = { abilities = { { 16497, "Stun Bomb", 4, "Stay spread out", { 15, 20 }, { 25, 30 } }, { 15609, "Hooked Net", 1, "Free rooted players", { 0, 8 }, { 15, 20 } }, { 15504, "Drink Healing Potion", 2, "Interrupt the potion if possible" }, { 16496, "Shoot", 1, "Pull him around a corner", nil, { 2, 3 } } }, strategy = "Zigris attacks from range and uses stuns and roots, so pull him around a corner to bring him into melee. Interrupt his potion use. Keep the group spread so Stun Bomb catches fewer players." },
        [9816] = { abilities = { { 16536, "Flame Buffet", 4, "Kill him before stacks grow", { 3, 11 }, { 4, 10 } }, { 16079, "Fire Nova", 4, "Melee watch their health", { 15, 16 }, { 11, 11 } } }, strategy = "Clear the orc incarcerators in the room first, which wakes the boss. Tank Emberseer in place and use fire resistance gear if available. Flame Buffet stacks up over time, so healers must keep pace and DPS should kill him quickly." },
        [9938] = { abilities = { { 13900, "Fiery Burst", 4, "Heal through the fire burst" }, { 24375, "War Stomp", 1, "Melee may be stunned" } }, strategy = "Magmus guards the throne room, and the room's fire hazards make it dangerous to stand in the wrong place. Tank him in a safe spot away from the flame vents. Healers keep the tank topped up and be ready for stuns in melee." },
        [10080] = { abilities = { { 12555, "Pummel", 1, "Healers watch for interrupts", { 9, 19 }, { 15, 24 } }, { 13730, "Demoralizing Shout", 1, "Heal the tank", { 5, 11 }, { 14, 35 } }, { 14516, "Strike", 1, "Heal the tank", nil, { 15, 25 } } }, strategy = "Sandarr is a rare troll warrior. Tank and burn him while healers watch the tank. He can interrupt casters, so healers should stay out of his reach." },
        [10081] = { abilities = { { 15667, "Sinister Strike", 1, "Heal the tank" } }, strategy = "Dustwraith is a rare ghost. Tank and burn it while healers watch the tank's health." },
        [10082] = { abilities = { { 6533, "Net", 1, "Break free from nets", { 0, 3 }, { 12, 25 } }, { 12551, "Frost Shot", 16, "Heal the slowed target", { 6, 11 }, { 5, 18 } }, { 15547, "Shoot", 1, "Pull him into melee", nil, { 2, 4 } } }, strategy = "Zerillis is a rare hunter. Have the tank close the distance and pull him into melee, then burn him down." },
        [10184] = { abilities = { { 18435, "Flame Breath", 4, "Tank faces it away" }, { 20019, "Engulfing Flames", 4, "Move out of the path" }, { 18431, "Bellowing Roar", 1, "Fear ward the tank" }, { 15847, "Tail Sweep", 1, "Stay out of her tail" }, { 19983, "Cleave", 1, "Face her away from melee" }, { 18392, "Fireball", 4, "Stay spread out" }, { 18500, "Wing Buffet", 1, "Tank keeps threat high" }, { 19633, "Knock Away", 1, "Tank against a wall" } }, strategy = "In phase one, tank Onyxia facing away from the raid and stay out of her tail. In phase two she flies, casts fireballs and spawns whelps, and occasionally does a deep breath that must be avoided. In phase three she lands, so watch for bellowing roar fears and the fissures in the ground." },
        [10220] = { abilities = {  }, strategy = "Halycon is a large worg boss with strong melee damage. Clear the surrounding worgs first, tank her away from the group, and keep heals on the tank." },
        [10263] = { abilities = { { 16046, "Blast Wave", 4, "Casters keep their distance", { 1, 1 }, { 10, 10 } }, { 15548, "Thunderclap", 8, "Melee watch their health", { 5, 5 }, { 15, 20 } }, { 15580, "Strike", 1, "Healers watch tank damage", { 5, 7 }, { 4, 6 } } }, strategy = "This rare demon hits hard in melee and has short-range area attacks. Tank him away from casters and keep ranged DPS at maximum range. Healers should prepare for group damage after each Blast Wave." },
        [10264] = { abilities = { { 16727, "War Stomp", 1, "Melee expect brief stuns", { 5, 9 }, { 16, 21 } } }, strategy = "Solakar appears after waves of whelps and handlers from the hatchery event. Clear each wave with AoE and crowd control. When Solakar arrives, tank him and burn him while healers cover the stun windows." },
        [10268] = { abilities = { { 16495, "Fatal Bite", 1, "Healers keep the tank high", { 7, 15 }, { 7, 15 } }, { 16128, "Infected Bite", 8, "Cure the disease", { 15, 20 }, { 10, 20 } }, { 8269, "Enrage", 1, "Save cooldowns for the enrage" } }, strategy = "Gizrul arrives shortly after Halycon dies, so stay ready. Tank him and cure Infected Bite as it lands. Save tank and healing cooldowns for when he enrages at low health." },
        [10339] = { abilities = { { 16337, "Chromatic Chaos", 64, "Healers prepare for group damage" }, { 16390, "Flame Breath", 4, "Tank faces it away", { 4, 4 }, { 10, 10 } }, { 16350, "Freeze", 16, "Dispel frozen players", { 11, 11 }, { 16, 16 } }, { 16359, "Corrosive Acid Breath", 8, "Tank faces it away", { 8, 8 }, { 7, 7 } }, { 10101, "Knock Away", 1, "Tank stays near a wall", { 23, 23 }, { 23, 23 } }, { 13360, "Knockdown", 1, "Healers watch the tank" } }, strategy = "Gyth arrives at the end of the arena waves carrying Rend Blackhand. Tank him facing away from the group so his breaths only hit the tank. Dispel players caught by Freeze. Rend dismounts during the fight and needs a second tank." },
        [10363] = { abilities = { { 16805, "Conflagration", 4, "Second tank ready to take aggro", { 8, 20 }, { 15, 45 } }, { 16419, "Flamestrike", 4, "Move out of the fire", { 9, 20 }, { 10, 35 } }, { 15754, "Cleave", 1, "Only the tank stands in front", { 7, 40 }, { 8, 35 } }, { 15588, "Thunderclap", 8, "Melee watch their health", { 7, 20 }, { 14, 25 } }, { 12097, "Pierce Armor", 1, "Healers watch the tank", { 8, 40 }, { 10, 30 } }, { 16789, "Rage", 1, "Healers prepare for higher damage", { 0, 5 }, { 30, 60 } } }, strategy = "Drakkisath fights alongside two Chromatic Elite Guards, which need offtanks or a clear kill order. Tank him facing away from the group. Move out of Flamestrike, and keep a second tank ready to grab him when Conflagration disables the main tank." },
        [10376] = { abilities = {  }, strategy = "A rare spider elite with melee attacks. Tank and burn it while healers watch the tank." },
        [10393] = { abilities = { { 16799, "Frostbolt", 16, "Interrupt this", nil, { 1, 2 } }, { 15499, "Frost Shock", 16, "Healers watch the target", { 6, 8 }, { 16, 20 } }, { 15230, "Arcane Bolt", 64, "Interrupt this", { 9, 11 }, { 9, 11 } } }, strategy = "Skul is a rare undead caster. Interrupt his bolts and burn him quickly. Purge or dispel Frost Armor if you can." },
        [10429] = { abilities = { { 13736, "Whirlwind", 1, "Melee step back during it", { 20, 20 }, { 18, 18 } }, { 15708, "Mortal Strike", 1, "Healers keep the tank high", { 9, 9 }, { 16, 16 } }, { 15754, "Cleave", 1, "Only the tank stands in front", { 5, 5 }, { 10, 10 } }, { 8269, "Enrage", 1, "Save cooldowns for the enrage" } }, strategy = "Rend joins the fight when he dismounts from Gyth. Pick him up with a tank and keep him facing away from the group. Melee should back off when he whirlwinds, and healers save cooldowns for his enrage." },
        [10430] = { abilities = { { 14100, "Terrifying Roar", 1, "Fear ward or tremor totem" }, { 16785, "Flamebreak", 4, "Spread out to limit splash" }, { 16636, "Berserker Charge", 1, "Expect sudden charges" }, { 20294, "Immolate", 4, "Dispel if possible" }, { 16788, "Fireball", 4, "Interrupt this" } }, strategy = "Clear the trash in the hall before pulling The Beast, since fears can scatter players into other packs. Tank him with his back against a wall. Use fear immunity or tremor totem, and spread out to reduce fire splash." },
        [10432] = { abilities = { { 16046, "Blast Wave", 4, "Melee stay alert for knockback" }, { 18399, "Flamestrike", 4, "Move out of the fire" }, { 28371, "Frenzy", 1, "Tank uses cooldowns on frenzy" } }, strategy = "Vectus is pulled with Marduk after the Viewing Room event. Move out of flamestrike and keep casters at range from his blast wave. Burn him down once Marduk is handled." },
        [10433] = { abilities = { { 17228, "Shadow Bolt Volley", 32, "Healers top off the group", { 5, 8 }, { 6, 14 } }, { 15754, "Cleave", 1, "Tank faces it away", { 15, 17 }, { 7, 22 } }, { 17695, "Defiling Aura", 32, "Kill him fast, stay mobile" }, { 12040, "Shadow Shield", 32, "Dispel or burn through shield", { 14, 15 }, { 1, 8 } } }, strategy = "Marduk is tanked alongside Vectus in the Viewing Room. Face him away from the group and heal through shadow volleys and his defiling aura. Purge or dispel his shadow shield when you can." },
        [10435] = { abilities = {  }, strategy = "Barthilas runs off deeper into the city if he spots you, so engage him quickly. Tank him and burn him down while healers watch the tank." },
        [10436] = { abilities = {  }, strategy = "Anastari is a banshee caster. Tank her and burn her quickly, and be ready to crowd control any party member she takes over. Healers stay alert for sudden damage." },
        [10437] = { abilities = {  }, strategy = "Nerub'enkan is a crypt lord who brings spider adds. Tank him in place, clear adds with AoE, and cure poisons as they land." },
        [10438] = { abilities = {  }, strategy = "Maleki is a frost-casting lich. Interrupt his spells, dispel his effects quickly and burn him down." },
        [10439] = { abilities = { { 17307, "Knockout", 1, "Healers watch the stunned tank" }, { 5568, "Trample", 1, "Only the tank stands close" } }, strategy = "Ramstein comes out after all three ziggurats are cleared. Tank him while the rest of the group stays behind him. Afterwards, prepare for a wave of undead adds before the Baron." },
        [10440] = { abilities = { { 17473, "Raise Dead", 32, "AoE the skeletons", { 15, 15 }, { 15, 15 } }, { 17393, "Shadow Bolt", 32, "Healers watch the targeted player", { 5, 5 }, { 10, 10 } }, { 15708, "Mortal Strike", 1, "Healers keep the tank high", { 12, 12 }, { 10, 25 } }, { 15754, "Cleave", 1, "Only the tank stands in front", { 8, 8 }, { 7, 17 } } }, strategy = "Tank Rivendare facing away from the group. He raises skeletons during the fight, so AoE them down or control them quickly. Healers must keep the tank high through Mortal Strike." },
        [10502] = { abilities = {  }, strategy = "A caster fought alongside Lord Alexei. Interrupt her spells and remove curses or fear effects. Kill her first if she is causing too much disruption." },
        [10503] = { abilities = { { 17773, "Summon Illusions", 32, "Find and kill the real Jandice" }, { 16098, "Curse of Blood", 32, "Remove the curse" }, { 8994, "Banish", 32, "Wait it out" } }, strategy = "Jandice periodically vanishes into a crowd of illusions. AoE the illusions or hunt for the real one, which is the one that still hits hard. Remove her curse and keep the tank on her when she reappears." },
        [10504] = { abilities = {  }, strategy = "Fought together with Lady Illucia in the Barov family room. Tank them separately and focus one at a time. Keep healers out of melee range." },
        [10505] = { abilities = {  }, strategy = "A caster in the Viewing Room events. Clear adds first, then tank her and interrupt her spells. Keep the group healed through any shadow damage." },
        [10506] = { abilities = { { 14515, "Dominate Mind", 32, "Polymorph or CC the controlled player", { 34, 48 }, { 44, 48 } }, { 17228, "Shadow Bolt Volley", 32, "Healers keep the group topped", { 42, 42 }, { 42, 42 } }, { 12889, "Curse of Tongues", 32, "Dispel the curse from casters", { 53, 53 }, { 35, 35 } }, { 18144, "Swoop", 1, "Keep healthy, avoid stacking", { 8, 8 }, { 15, 15 } }, { 12882, "Wing Flap", 8, "Expect knockback near him", { 15, 15 }, { 13, 13 } }, { 8379, "Disarm", 1, "Tank keeps threat when disarmed", { 22, 22 }, { 11, 11 } }, { 6016, "Pierce Armor", 1, "Heal the tank through it", { 18, 18 }, { 12, 12 } } }, strategy = "Kirtonos alternates between bird and caster forms. Tank him away from the group and keep curses off healers. If a player is mind controlled, crowd control them rather than killing them. Burn him steadily and heal through the shadow volleys." },
        [10507] = { abilities = {  }, strategy = "A large melee brute that hits hard and cleaves. Tank him facing away from the group and heal the tank steadily. DPS from behind." },
        [10508] = { abilities = {  }, strategy = "A frost lich at the bottom of the school. Tank him and keep healers ready for frost damage and slows. Dispel what you can and keep the tank topped off." },
        [10509] = { abilities = { { 11972, "Shield Bash", 1, "Casters watch for interrupts", nil, { 4, 6 } }, { 15749, "Shield Charge", 1, "Expect sudden charges", { 6, 9 }, { 11, 14 } }, { 14516, "Strike", 1, "Healers watch tank damage", { 4, 7 }, { 7, 10 } } }, strategy = "Jed is a rare elite who does not always spawn. Tank him and keep casters at range. He has no special mechanics beyond his melee attacks and interrupts." },
        [10516] = { abilities = { { 14907, "Frost Nova", 16, "Break or wait out roots", { 6, 10 }, { 11, 14 } } }, strategy = "The Unforgiven spawns with several ghost adds. Tank the boss and use AoE to clear the ghosts. Melee should be ready to break or wait out Frost Nova roots." },
        [10558] = { abilities = { { 16798, "Enchanting Lullaby", 32, "Dispel the sleep effect", { 7, 9 }, { 20, 25 } }, { 14443, "Multi-Shot", 64, "Stay spread out", { 9, 14 }, { 9, 14 } }, { 16244, "Demoralizing Shout", 1, "Healers watch the tank", { 3, 5 }, { 12, 19 } } }, strategy = "Forresten fights from range, so pull him into melee range. Dispel players hit by Enchanting Lullaby. Keep the group spread to reduce Multi-Shot damage." },
        [10584] = { abilities = { { 16508, "Intimidating Roar", 1, "Fear ward or tremor the tank", { 10, 20 }, { 21, 28 } }, { 16509, "Rend", 1, "Healers keep up with bleed", { 9, 14 }, { 17, 21 } }, { 15580, "Strike", 1, "Healers watch tank damage" } }, strategy = "Urok appears after waves of ogres from his summoning event, so control those adds first. Tank Urok in place and keep healers ready for fear breaks. Clean up any remaining adds after he dies." },
        [10596] = { abilities = { { 16104, "Crystallize", 1, "Cure stunned players quickly", { 7, 15 }, { 10, 17 } }, { 16468, "Mother's Milk", 1, "Healers watch the tank", { 1, 1 }, { 7, 15 } }, { 16103, "Summon Spire Spiderling", 1, "AoE down the spiderlings" } }, strategy = "Clear the nearby spiders before pulling. Tank Mother Smolderweb while AoE classes clear the spiderlings she summons. Cure Crystallize quickly so players are not stunned for long." },
        [10808] = { abilities = { { 17470, "Ravenous Claw", 1, "Healers keep the tank high" }, { 8599, "Enrage", 1, "Save cooldowns for the enrage" } }, strategy = "Clear the courtyard packs and Timmy appears. Tank him in place and burn him down. Healers save cooldowns for his enrage." },
        [10809] = { abilities = { { 14331, "Vicious Rend", 1, "Healers keep up with bleed" } }, strategy = "A rare elite with a strong bleed on the tank. Tank him and burn him while healers keep the tank topped." },
        [10811] = { abilities = { { 17274, "Pyroblast", 4, "Interrupt this" }, { 17366, "Fire Nova", 4, "Melee step back", { 7, 12 }, { 7, 12 } }, { 17293, "Burning Winds", 4, "Healers watch group damage" } }, strategy = "Galford is a fire caster. Interrupt Pyroblast every time. Melee should step out for Fire Nova, and fire resistance helps if available." },
        [10812] = { abilities = { { 17405, "Domination", 64, "Control charmed allies until it ends", { 38, 57 }, { 27, 28 } }, { 13704, "Psychic Scream", 32, "Fear ward or tremor totem", { 49, 61 }, { 28, 28 } }, { 12098, "Sleep", 32, "Dispel the sleep", { 31, 47 }, { 10, 19 } }, { 17287, "Mind Blast", 32, "Interrupt this", { 31, 32 }, { 6, 26 } }, { 17399, "Shadow Shock", 32, "Healers watch shadow damage", { 28, 39 }, { 7, 22 } }, { 17286, "Crusader's Hammer", 2, "Healers watch the targeted player" }, { 17281, "Crusader Strike", 1, "Healers watch the tank" }, { 17284, "Holy Strike", 2, "Healers watch the tank" } }, strategy = "The fight opens against Grand Crusader Dathrohan, who uses holy melee attacks. At low health he becomes Balnazzar, a demon who charms, sleeps and fears players. Have fear protection ready and keep charmed allies controlled until the effect wears off." },
        [10899] = { abilities = { { 16172, "Head Crack", 1, "Healers watch the tank", { 3, 6 }, { 3, 6 } }, { 6253, "Backhand", 1, "Healers watch the tank", { 5, 8 }, { 4, 6 } }, { 15580, "Strike", 1, "Healers keep the tank topped", { 5, 8 }, { 6, 10 } } }, strategy = "Goraluk is a straightforward melee boss. Tank him in place and burn him quickly. Healers focus the tank through his stuns." },
        [10901] = { abilities = {  }, strategy = "A caster boss in his own study room. Tank him and remove diseases and debuffs from the group. Interrupt casts and keep the tank healed." },
        [10997] = { abilities = { { 17279, "Summon Crimson Rifleman", 64, "Kill the riflemen quickly" }, { 10101, "Knock Away", 1, "Tank stays near a wall" }, { 15615, "Pummel", 1, "Casters watch for interrupts" }, { 17278, "Cannon Fire", 4, "Move out of the blast" } }, strategy = "Willey summons Crimson Riflemen during the fight, so offtank or kill them fast. Tank him with his back to a wall. Healers should watch the whole group, since the riflemen spread damage." },
        [11082] = { abilities = { { 15615, "Pummel", 1, "Casters watch for interrupts", { 6, 11 }, { 12, 17 } }, { 15618, "Snap Kick", 1 } }, strategy = "A quick melee target with interrupts. Tank him and burn him down; there is little else to watch for." },
        [11121] = { abilities = { { 16867, "Banshee Curse", 32, "Remove the curse quickly", { 7, 10 }, { 15, 15 } } }, strategy = "The Swordsmith appears as part of a quest event. Tank him and decurse Banshee Curse on affected players while DPS burns him down." },
        [11143] = { abilities = { { 7713, "Wailing Dead", 32, "Fear ward or tremor totem" }, { 12889, "Curse of Tongues", 32, "Remove from casters" }, { 8552, "Curse of Weakness", 32, "Remove from the tank" }, { 17831, "Call of the Grave", 32, "Dispel the curse" }, { 6253, "Backhand", 1, "Healers watch the tank" } }, strategy = "Malown appears after you open the postboxes around the Live side. Tank him in a cleared area and use fear protection for Wailing Dead. Decurse quickly, prioritizing casters and the tank." },
        [11261] = { abilities = { { 8269, "Enrage", 1, "Save burst for the enrage" }, { 18103, "Backhand", 1, "Heal the stunned tank" }, { 16509, "Rend", 1, "Heal through the bleed" } }, strategy = "Tank Krastinov and focus him down. He enrages at low health, so save cooldowns for the end. Healers cover the tank during backhand stuns and rend bleeds." },
        [11380] = { abilities = { { 24262, "Summon Brain Wash Totem", 32, "Kill the totem fast" }, { 24309, "Powerful Healing Ward", 1, "Destroy the healing ward" }, { 24306, "Delusions of Jin'do", 32, "Kill the shades" }, { 17172, "Hex", 8, "Dispel the hex" }, { 24308, "Summon Shade of Jin'Do", 32, "Kill the shades" }, { 24261, "Brain Wash", 32, "Kill the totem fast" }, { 24466, "Banish", 32, "Dispel the banish" }, { 24458, "Shadow Shock", 32, "Heal through it" } }, strategy = "Jin'do summons totems and wards that must be killed quickly. Players hit by delusions should attack the shades. Dispel hex and keep the raid focused on totems first." },
        [11382] = { abilities = { { 24314, "Threatening Gaze", 1, "Stop all actions when watched" }, { 13736, "Whirlwind", 1, "Melee step out of whirlwind" }, { 24312, "Level Up", 1, "Avoid letting raid die" }, { 24408, "Charge", 1, "Stay alert for charges" }, { 16856, "Mortal Strike", 1, "Heal the tank through it" }, { 19134, "Intimidating Shout", 1, "Tank uses fear immunity" }, { 20691, "Cleave", 1, "Face him away from melee" }, { 24317, "Sunder Armor", 1, "Tank keeps threat high" } }, strategy = "Mandokir fixates on a player with his gaze, and anyone acting during it gets executed. Stop everything when targeted, and melee step out of whirlwinds. Each death levels him up, so avoid deaths and kill his raptor first." },
        [11467] = { abilities = { { 21060, "Blind", 8, "Dispel or wait it out", { 7, 11 }, { 16, 21 } }, { 12540, "Gouge", 1, "Off-tank picks up after gouge", { 6, 8 }, { 9, 12 } }, { 15581, "Sinister Strike", 1, "Heal the tank through it", { 3, 5 }, { 5, 7 } } }, strategy = "A rare rogue boss. Have a second player ready to hold threat when she gouges the tank. Dispel blind and burn her quickly." },
        [11486] = { abilities = { { 22920, "Arcane Blast", 64, "Tank uses taunt after blast" }, { 15589, "Whirlwind", 1, "Melee step out of whirlwind" }, { 22995, "Summon", 64, "Expect to be pulled in" }, { 20537, "Counterspell", 64, "Casters avoid long casts", nil, { 1, 4 } }, { 3391, "Thrash", 1, "Heal the tank through it" } }, strategy = "Tortheldrin knocks players away and pulls them back to him. Melee should step out during whirlwind, and the tank must taunt after arcane blast threat drops. Casters watch for counterspell." },
        [11487] = { abilities = { { 7645, "Dominate Mind", 32, "CC the controlled player" }, { 17287, "Mind Blast", 32, "Interrupt this" }, { 22919, "Mind Flay", 32, "Interrupt this" }, { 17146, "Shadow Word: Pain", 32, "Dispel it" }, { 22917, "Shadowform", 32, "Shadow protection helps" } }, strategy = "A shadow priest who controls minds and drains health. Interrupt his casts, dispel shadow word pain, and crowd control any controlled player. Shadow resistance buffs help a lot." },
        [11488] = { abilities = { { 22908, "Volley", 64, "Move out of the volley", { 30, 35 }, { 60, 65 } }, { 22910, "Immolation Trap", 4, "Avoid stepping on traps", { 7, 10 }, { 10, 15 } }, { 20735, "Multi-Shot", 64, "Spread out a bit" }, { 22914, "Concussive Shot", 64, "Expect slows", { 5, 7 }, { 16, 20 } } }, strategy = "A hunter boss with a pet bear. Control or kill the pet first. Spread out to limit multi-shot, move out of volley, and avoid her traps while the tank holds her in melee." },
        [11489] = { abilities = { { 22994, "Entangle", 8, "Dispel the roots", { 6, 12 }, { 15, 20 } }, { 5568, "Trample", 1, "Melee stay spread", { 5, 9 }, { 9, 14 } }, { 22916, "Uppercut", 1, "Heal the knocked tank", { 9, 12 }, { 12, 15 } }, { 8269, "Enrage", 1, "Burn him at low health" } }, strategy = "A treant boss guarded by ancients. Kill nearby adds first, then tank him in place. Dispel entangle so players can act, and heal through uppercut knockbacks." },
        [11490] = { abilities = { { 22651, "Sacrifice", 32, "Burst him to free the victim" }, { 22478, "Intense Pain", 32, "Healers top up the tank" } }, strategy = "Tank Zevrim in place and keep him away from the casters. Sacrifice pins a player and drains them, so healers must keep that target alive while DPS pushes damage. Intense Pain raises his damage output, so healers focus the tank while it is active." },
        [11492] = { abilities = { { 22662, "Wither", 8, "Healers prepare for group damage" }, { 22661, "Enervate", 1, "Tank keeps him faced away" }, { 22689, "Mangle", 1, "Tank uses cooldowns in wolf form" }, { 22660, "Dire Wolf Form", 1, "Expect heavier melee damage" }, { 22688, "Tree Form", 1, "Push damage while he heals" }, { 7948, "Wild Regeneration", 8, "Burn through the heal" }, { 22128, "Thorns", 8, "Melee watch their health" } }, strategy = "Alzzin swaps between forms, so the tank should hold him in a fixed spot facing away from the group. Healers keep the tank topped up during wolf form and watch group-wide damage. DPS should push hard when he shifts to heal himself." },
        [11496] = { abilities = { { 22899, "Eye of Immol'thar", 32, "Kill the eyes quickly" }, { 22950, "Portal of Immol'thar", 64, "Return to the fight" }, { 5568, "Trample", 1, "Melee stay spread" }, { 16128, "Infected Bite", 8, "Cure the disease" }, { 8269, "Enrage", 1, "Save burst for enrage" } }, strategy = "Free Immol'thar by destroying the five pylons. Kill the eyes he summons quickly and cure his infected bite. Tank him against a wall and burn him, saving cooldowns for his enrage." },
        [11501] = { abilities = { { 15708, "Mortal Strike", 1, "Heal the tank through it" }, { 16727, "War Stomp", 1, "Melee expect a stun" }, { 22886, "Berserker Charge", 1, "Stay alert for charges" }, { 15572, "Sunder Armor", 1, "Tank keeps threat high" } }, strategy = "King Gordok is fought with Cho'Rush nearby. Off-tank or CC Cho'Rush while the main tank holds Gordok. Healers cover mortal strike and war stomp stuns. Kill him to crown a new king and claim tribute." },
        [11502] = { abilities = { { 20566, "Wrath of Ragnaros", 4, "Melee ready to run back in" }, { 20565, "Magma Blast", 4, "Ranged stay in melee range of tank" }, { 21154, "Might of Ragnaros", 1, "Off tank ready after knockback" }, { 21155, "Intense Heat", 4, "Heal through the heat" } }, strategy = "Ragnaros knocks back melee with Wrath of Ragnaros, so warriors should rotate taunts and avoid lava. Ranged stand close enough that he never lacks a melee target, or he will cast Magma Blast at them. After three minutes he submerges and Sons of Flame spawn; kill them quickly before he returns. Fire resistance gear is very helpful." },
        [11517] = { abilities = { { 5532, "Cleave", 1, "Melee stand behind him", { 8, 15 }, { 5, 12 } } }, strategy = "A simple melee boss. The tank faces him away from the group, and melee attack from behind to avoid his Cleave. Clear nearby troggs first so they do not join the fight." },
        [11518] = { abilities = { { 20800, "Immolate", 4, "Dispel Immolate if possible", { 14, 14 }, { 6, 23 } }, { 18267, "Curse of Weakness", 32, "Remove the curse from the tank", { 5, 5 }, { 7, 16 } } }, strategy = "Jergosh is a caster, so interrupt him and stay close to limit his spells. Dispel Immolate and remove Curse of Weakness from the tank when you can. DPS should focus him quickly before the burn damage adds up." },
        [11519] = { abilities = { { 744, "Poison", 8, "Cure poison on the tank" }, { 14873, "Sinister Strike", 1, "Healer watches tank health" } }, strategy = "Bazzalan is a rogue-style fighter who poisons and strikes the tank. Cure poison when it lands and keep the tank healed through Sinister Strike spikes. DPS him down quickly; he has little else to worry about." },
        [11520] = { abilities = { { 11970, "Fire Nova", 4, "Healer tops up after each nova", { 9, 14 }, { 10, 18 } }, { 18072, "Uppercut", 1, "Tank keeps back to a wall", { 7, 12 }, { 6, 16 } } }, strategy = "Tank him with his back away from ledges so Uppercut does not knock the tank into other packs. He pulses Fire Nova that hits everyone nearby, so the healer should keep the group topped off. Ranged can stand back to avoid the nova while melee burn him down." },
        [11583] = { abilities = { { 22992, "Shadow Flame", 32, "Wear an Onyxia Scale Cloak" }, { 22686, "Bellowing Roar", 1, "Use Fear Ward or Tremor Totems" }, { 22687, "Veil of Shadow", 32, "Decurse the tank quickly" }, { 23603, "Wild Polymorph", 64, "Mages stop casting during the call" }, { 23401, "Corrupted Healing", 32, "Priests stop healing during the call" }, { 23436, "Corrupt Weapon", 32, "Hunters unequip ranged weapons early" }, { 23364, "Tail Lash", 1, "Never stand behind him" }, { 20691, "Cleave", 1, "Only the tank in front" } }, strategy = "Phase one is a long add phase where the raid kills drakonids from both sides until enough have died. Nefarian then lands; tank him facing away and keep melee at his sides away from his tail. He periodically calls on a class with a harmful effect, so each class must know its response. At 20 percent the dead drakonids rise again as skeletons, so AoE them down while finishing the boss." },
        [11622] = { abilities = { { 16727, "War Stomp", 1, "Melee expect a stun", { 15, 21 }, { 13, 19 } }, { 10101, "Knock Away", 1, "Tank backs into a wall", { 7, 12 }, { 10, 17 } }, { 18368, "Strike", 1, "Heal the tank through hits", { 6, 11 }, { 7, 11 } } }, strategy = "A tank-and-spank skeletal giant. Put the tank against a wall to limit knock away, and have healers prepare for the war stomp stun on melee. Clear the room adds first." },
        [11981] = { abilities = { { 23342, "Frenzy", 1, "Hunters Tranquilizing Shot right away" }, { 22539, "Shadow Flame", 32, "Wear an Onyxia Scale Cloak" }, { 23339, "Wing Buffet", 1, "Off tank ready after knockback" }, { 3391, "Thrash", 1, "Healers keep tank topped" } }, strategy = "Flamegor frenzies often and must be calmed with Tranquilizing Shot each time, so set up a hunter rotation. Everyone needs an Onyxia Scale Cloak for Shadow Flame. Face him away from the raid and use two tanks to cover Wing Buffet threat loss." },
        [11982] = { abilities = { { 19408, "Panic", 32, "Use Fear Ward and Tremor Totems", { 10, 10 }, { 30, 35 } }, { 19451, "Frenzy", 1, "Hunters Tranquilizing Shot right away", { 15, 15 }, { 15, 20 } }, { 19411, "Lava Bomb", 1, "Move out of the fire", { 12, 12 }, { 12, 15 } } }, strategy = "Magmadar fears everyone nearby, so use Fear Ward on the tank and Tremor Totems in melee groups. Hunters remove his Frenzy with Tranquilizing Shot. Move out of the lava bomb patches and keep ranged spread behind him." },
        [11983] = { abilities = { { 22539, "Shadow Flame", 32, "Wear an Onyxia Scale Cloak" }, { 23341, "Flame Buffet", 4, "Break line of sight to drop stacks" }, { 23339, "Wing Buffet", 1, "Swap tanks after the knockback" }, { 3391, "Thrash", 1, "Healers keep tank topped" } }, strategy = "Everyone needs an Onyxia Scale Cloak to survive Shadow Flame. Flame Buffet stacks on the whole raid, so ranged and healers rotate behind a pillar to clear stacks. Use two tanks and swap after Wing Buffet throws threat." },
        [11988] = { abilities = { { 19798, "Earthquake", 1, "Melee back off below 10 percent" }, { 20553, "Golemagg's Trust", 1, "Keep dogs away from Golemagg" }, { 20228, "Pyroblast", 4, "Heal targets through the burn" }, { 19820, "Mangle", 1, "Healers watch the tank closely" }, { 3391, "Thrash", 1, "Healers keep tank topped" } }, strategy = "Tank Golemagg in place while two tanks hold his Core Rager dogs away from him. The dogs cannot die before he does, so ignore them. Damage on Golemagg rises as his stacking debuff builds, and below 10 percent melee should back off from Earthquake." },
        [12017] = { abilities = { { 24573, "Mortal Strike", 1, "Healers top the tank after hits" }, { 23331, "Blast Wave", 4, "Ranged stay out of its range" }, { 18670, "Knock Away", 1, "Off tank ready to taunt" }, { 15284, "Cleave", 1, "Only tanks stand in front" } }, strategy = "Avoid the suppression room traps on the way in, then pull Broodlord back to a corner. Two tanks share threat because Knock Away drops aggro on the main tank. Ranged should stay back from Blast Wave and healers must keep the tank high through Mortal Strike." },
        [12018] = { abilities = { { 20619, "Magic Reflection", 64, "Casters stop casting during reflect" }, { 21075, "Damage Shield", 64, "Melee stop attacking during shield" }, { 20620, "Aegis of Ragnaros", 32, "Kill his guards instead" }, { 21086, "Encouragement", 1 } }, strategy = "Majordomo cannot be killed; the goal is to defeat his eight Flamewaker guards and healers. Crowd control several adds, kill the healers first, and stop attacking when Magic Reflection or Damage Shield is up. Once all guards fall he surrenders and summons Ragnaros." },
        [12056] = { abilities = {  }, strategy = "Baron Geddon turns random players into Living Bombs, who must run away from the raid before they explode. He also casts an Inferno around himself, so melee step out when it starts. Dispel his mana-draining Ignite Mana, keep the raid spread, and bring fire resistance." },
        [12057] = { abilities = { { 19492, "Antimagic Pulse", 1, "Rebuff after the pulse strips buffs" }, { 19497, "Eruption", 4, "Banish adds rather than kill them" }, { 19516, "Enrage", 1, "Kill adds slowly or banish them" }, { 19496, "Magma Shackles", 4, "Expect slowed movement nearby" }, { 15732, "Immolate", 4, "Heal through the burn" } }, strategy = "Garr has eight Firesworn adds; warlocks banish several and the rest are tanked separately. Killed adds explode and make Garr stronger, so many groups leave them banished and focus Garr. Keep melee away from dying adds and rebuff after Antimagic Pulse." },
        [12098] = { abilities = {  }, strategy = "Sulfuron is guarded by four Flamewaker Priests that heal each other and the boss. Interrupt their heals and kill the priests one at a time before focusing Sulfuron. His Inspire and knockback make tanking tricky, so keep a backup tank ready." },
        [12118] = { abilities = {  }, strategy = "Lucifron casts a raid-wide curse and a shadow damage effect, and his two Flamewaker Protectors can mind control players. Kill the adds first, decurse quickly, and keep the raid spread so mind controlled players can be handled. Tank Lucifron away from the add tanks." },
        [12201] = { abilities = { { 21909, "Dust Field", 8, "Melee step out of the dust", { 5, 20 }, { 10, 30 } }, { 21832, "Boulder", 1, "Ranged players watch for boulders", { 8, 12 }, { 10, 30 } }, { 21869, "Repulsive Gaze", 1, "Tank faces her away from group", { 5, 10 }, { 35, 45 } }, { 3391, "Thrash", 1, "Heal the tank through bursts", { 8, 12 }, { 8, 30 } } }, strategy = "Theradras is the final boss and hits hard. The tank faces her away from the group, while ranged and healers spread out at a safe distance. Melee should back out when Dust Field goes off, and healers must watch for boulder damage on ranged players." },
        [12203] = { abilities = {  }, strategy = "Landslide is a large earth elemental with no abilities listed here. Tank him with your back to a wall to avoid being knocked around the room. DPS should kill any small elementals that show up so they do not overwhelm the healer." },
        [12225] = { abilities = {  }, strategy = "Celebras is a caster boss with no useful abilities listed here. The tank should keep him in melee and interrupt him whenever possible. DPS focus him down and switch to any adds he brings. After the fight you can talk to his spirit for the Scepter of Celebras quest." },
        [12236] = { abilities = { { 7964, "Smoke Bomb", 1, "Move out of the smoke", { 8, 12 }, { 14, 18 } }, { 21390, "Multi-Shot", 64, "Spread out to limit the hits", nil, { 7, 10 } }, { 21655, "Blink", 8, "Tank re-grabs him after blinks", { 20, 30 }, { 20, 30 } } }, strategy = "Lord Vyletongue fights alongside satyr guards, so mark and control or kill the guards first. He blinks away and shoots from range, so the tank must chase him back into position. Keep ranged players spread out and move out of smoke clouds quickly." },
        [12237] = { abilities = { { 15593, "War Stomp", 1, "Melee may get stunned, heal through", { 11, 16 }, { 15, 21 } }, { 13446, "Strike", 1 } }, strategy = "Meshlok is an optional rare plant boss. The tank holds him while DPS burns him down. Healers should be ready for short stuns from War Stomp hitting players in melee range." },
        [12258] = { abilities = { { 11427, "Cleave", 1, "Melee stay behind him" }, { 15976, "Puncture", 1, "Heal the tank through bleeds", { 8, 12 }, { 12, 16 } }, { 3391, "Thrash", 1, "Tank expects bursts of hits", { 8, 12 }, { 15, 20 } } }, strategy = "Razorlash is a pure melee fight. The tank faces him away from the group so Cleave only hits the tank, and melee DPS attack from behind. Healers focus on the tank, who will take extra damage from Thrash and Puncture bleeds." },
        [12259] = { abilities = { { 19716, "Gehennas' Curse", 32, "Decurse the raid quickly" }, { 19717, "Rain of Fire", 4, "Move out of the fire" }, { 19728, "Shadow Bolt", 32, "Heal the target through it" } }, strategy = "Kill the two Flamewaker adds first, then Gehennas. His curse greatly reduces healing, so mages and druids decurse constantly. Move out of Rain of Fire and keep healers topping off Shadow Bolt targets." },
        [12264] = { abilities = { { 19712, "Arcane Explosion", 64, "Ranged stay out of melee range" }, { 19713, "Shazzrah's Curse", 64, "Decurse the raid quickly" }, { 23138, "Gate of Shazzrah", 64, "Tank re-establishes threat after blink" }, { 19715, "Counterspell", 64, "Casters stagger casts near him" }, { 19714, "Deaden Magic", 64, "Dispel or Purge his shield" } }, strategy = "Shazzrah blinks to a random player and pulses Arcane Explosion, so keep the raid spread and ready to react. Decurse his curse and purge or dispel Deaden Magic. Tanks must quickly pick him back up after each blink." },
        [12397] = { abilities = { { 21056, "Mark of Kazzak", 32, "Run away before mana runs out", { 10, 10 }, { 10, 10 } }, { 21063, "Twisted Reflection", 64, "Dispel it quickly", { 12, 12 }, { 15, 15 } }, { 21054, "Capture Soul", 32, "Avoid deaths, they heal him" }, { 21341, "Shadow Bolt Volley", 32, "Heal through the volleys", { 8, 12 }, { 4, 6 } }, { 21066, "Void Bolt", 32, "Heal the target through it", { 10, 10 }, { 9, 12 } }, { 8078, "Thunderclap", 8, "Melee heal through damage", { 4, 8 }, { 7, 12 } }, { 16044, "Cleave", 1, "Only the tank in front", { 3, 3 }, { 7, 10 } } }, strategy = "Lord Kazzak heals from players who die and from Twisted Reflection, so dispel quickly and keep people alive. Players with Mark of Kazzak drain mana and explode when empty, so they should move away. He enrages after a few minutes, so burn hard." },
        [12435] = { abilities = { { 23023, "Conflagration", 4, "Off tank ready to taunt" }, { 22425, "Fireball Volley", 4, "Spread out and heal through volleys" }, { 24375, "War Stomp", 1, "Melee be ready for the stun" }, { 19632, "Cleave", 1, "Only the tank stands in front" } }, strategy = "In the first phase, one player mind controls Razorgore to destroy all the eggs while the raid holds off the waves of adds in the room. Keep the adds off the controller and the healers. Once every egg is gone Razorgore becomes hostile; tank him, keep melee off his front, and spread to limit Fireball Volley and Conflagration damage." },
        [12876] = { abilities = { { 15043, "Frostbolt", 16, "Interrupt this", nil, { 2, 2 } }, { 14907, "Frost Nova", 16, "Melee get out after nova", { 7, 12 }, { 14, 19 } } }, strategy = "Baron Aquanis is summoned from the Fathom Stone and casts frost spells. Interrupt Frostbolt and expect roots from Frost Nova. Focus him down while the healer covers frost damage." },
        [12902] = { abilities = { { 12167, "Lightning Bolt", 8, "Interrupt this", nil, { 2, 2 } }, { 12550, "Lightning Shield", 8, "Melee watch shield damage" } }, strategy = "Lorgus Jett is a shaman who casts Lightning Bolt and uses Lightning Shield. Interrupt bolts and melee should watch their health. Kill him quickly." },
        [13020] = { abilities = { { 23620, "Burning Adrenaline", 4, "Run out of the raid before exploding" }, { 23461, "Flame Breath", 4, "Tank faces it away from raid" }, { 15847, "Tail Sweep", 1, "Never stand behind the dragon" }, { 23513, "Essence of the Red", 2, "Spam abilities, mana is unlimited" }, { 19983, "Cleave", 1, "Only the tank in front" }, { 23462, "Fire Nova", 4, "Heal through the pulsing damage" } }, strategy = "Vaelastrasz starts at low health and the raid gets unlimited mana and rage, so this is a pure damage race. Burning Adrenaline goes on the tank and random players; anyone affected must leave the raid before they explode, and a new tank must taunt immediately. Stand at his sides, keep a tank rotation ready, and bring fire resistance." },
        [13280] = { abilities = { { 22421, "Massive Geyser", 1, "Fight away from ledges", { 7, 15 }, { 7, 15 } }, { 22419, "Riptide", 16, "Healers expect frequent water damage" }, { 22714, "Summon Hydroling", 2, "Kill or offtank the Hydrolings" }, { 22420, "Submersion", 16, "Wait for him to resurface", { 2, 6 }, { 45, 65 } } }, strategy = "Tank Hydrospawn in the open so knockups do not throw anyone into nearby packs. Pick up the Hydrolings he summons and kill or control them quickly. When he submerges, regroup and wait for him to surface before resuming DPS." },
        [13282] = { abilities = {  }, strategy = "Noxxion is a poison elemental with no listed abilities here, so treat him as a straightforward tank and spank. The tank holds him in place while DPS burns him down. Have poison cures ready and switch to any adds that appear during the fight." },
        [13596] = { abilities = { { 16495, "Fatal Bite", 1, "Heal the tank hard" }, { 15976, "Puncture", 1, "Tank takes bleed damage" } }, strategy = "Rotgrip is a large crocolisk in the inner area with heavy melee attacks. The tank holds him in place while DPS attack from the sides or behind. Healers need to focus on the tank, as Fatal Bite and Puncture hit hard." },
        [13601] = { abilities = { { 21833, "Goblin Dragon Gun", 4, "Stay out of the frontal cone", { 7, 8 }, { 16, 20 } }, { 29419, "Flash Bomb", 1, "Expect to be briefly disabled", { 5, 5 }, { 7, 8 } }, { 9143, "Bomb", 4, "Spread out to avoid bombs", { 2, 3 }, { 7, 8 } } }, strategy = "Gizlock is a goblin engineer who mixes ranged shots with fire and bomb attacks. The tank should bring him to the group and face him away from everyone else. Ranged players spread out so bombs and the Dragon Gun cone hit as few people as possible." },
        [13718] = { abilities = { { 16098, "Curse of Blood", 32, "Remove the curse quickly", { 15, 29 }, { 15, 29 } }, { 15848, "Festering Rash", 8, "Cure the disease", { 16, 29 }, { 16, 29 } }, { 15501, "Earth Shock", 8, "Interrupt or heal through shocks", { 5, 10 }, { 5, 10 } } }, strategy = "The Nameless Prophet is a caster Khan spirit. The tank keeps him in melee while DPS burns him down. Decurse and cure disease as soon as they land to keep healing pressure low." },
        [13738] = { abilities = { { 14030, "Hooked Net", 1, "Healers watch rooted players", { 0, 10 }, { 13, 18 } }, { 18651, "Multi-Shot", 64, "Spread out to limit the hits", { 5, 8 }, { 9, 15 } } }, strategy = "Veng is one of the Khan spirits and fights as a ranged attacker. The tank should pull him into melee range quickly so he spends less time shooting. Ranged players should stand apart to reduce Multi-Shot damage, and healers should keep an eye on anyone caught in his net." },
        [13739] = { abilities = { { 6533, "Net", 1, "Tank may be rooted briefly", { 0, 10 }, { 12, 25 } }, { 15667, "Sinister Strike", 1, nil, nil, { 8, 13 } }, { 15795, "Throw", 1, "Ranged attack on random players", { 0, 1 }, { 2, 4 } } }, strategy = "Maraudos is a Khan spirit with a mix of melee and ranged attacks. The tank should keep him in melee and stay in range even when netted. Healers keep the tank topped up and watch for anyone hit by his thrown weapons." },
        [13740] = { abilities = { { 15572, "Sunder Armor", 1, "Healers watch the tank's armor drop", { 6, 8 }, { 5, 12 } }, { 9128, "Battle Shout", 1, nil, { 4, 11 }, { 12, 18 } } }, strategy = "Magra is a warrior-type Khan spirit. The tank holds her while DPS burns her quickly, since stacking Sunder Armor makes the tank take more damage over time. Healers should ramp up healing on the tank as the fight goes on." },
        [13741] = { abilities = { { 15284, "Cleave", 1, "Tank faces him away", { 13, 14 }, { 8, 8 } }, { 9080, "Hamstring", 1, "Tank stays in melee range", { 7, 12 }, { 8, 8 } } }, strategy = "Gelk is a melee Khan spirit. Face him away from the group so Cleave only hits the tank. Melee DPS attack from behind while healers focus on the tank." },
        [13742] = { abilities = { { 16244, "Demoralizing Shout", 1, "Tank and melee deal less damage", { 3, 15 }, { 43, 43 } }, { 14516, "Strike", 1, nil, { 4, 12 }, { 5, 12 } } }, strategy = "Kolk is a melee Khan spirit. The tank picks him up and holds him in place while DPS kills him. This is a simple fight with steady tank damage, so healers focus on the tank." },
        [14020] = { abilities = { { 23170, "Brood Affliction: Bronze", 64, "Use Hourglass Sand to remove it" }, { 23310, "Time Lapse", 64, "Hide behind the door during breath" }, { 23315, "Ignite Flesh", 4, "Tanks swap when stacks get high" }, { 23313, "Corrosive Acid", 8, "Tanks swap when stacks get high" }, { 23187, "Frost Burn", 16, "Break line of sight to avoid" }, { 23308, "Incinerate", 4, "Break line of sight to avoid" }, { 23128, "Frenzy", 1, "Hunters Tranquilizing Shot right away" }, { 22277, "Elemental Shield", 64, "Switch spell school to his weakness" } }, strategy = "Chromaggus has two random breaths each week; the raid hides behind the gate when he breathes to avoid them. Brood Afflictions must be removed quickly by the right dispel, with Hourglass Sand for Bronze, because five types turn a player into a Chromatic mutation. Hunters calm his Frenzy and casters change spell school as his vulnerability shifts. Push hard in the final 20 percent when he enrages." },
        [14321] = { abilities = { { 15580, "Strike", 1, "Heal the tank through it" }, { 10101, "Knock Away", 1, "Tank against a wall" }, { 8269, "Enrage", 1, "Burn him at low health" } }, strategy = "A melee ogre guard. For a tribute run, leave him alive. Otherwise tank him near a wall and DPS from behind." },
        [14322] = { abilities = { { 15577, "Whirlwind", 1, "Melee step out of whirlwind", { 2, 6 }, { 7, 10 } }, { 22833, "Booze Spit", 1, "Stay behind him", { 7, 12 }, { 15, 22 } }, { 16740, "War Stomp", 1, "Expect a short stun", { 12, 15 }, { 12, 16 } }, { 22835, "Drunken Rage", 1, "Tank uses cooldowns" }, { 8269, "Enrage", 1, "Burn him at low health" } }, strategy = "A drunk ogre with a whirlwind and booze spit. Tank him with melee ready to step out of whirlwinds. Avoid his front cone and heal through his drunken rage." },
        [14323] = { abilities = { { 22856, "Ice Lock", 16, "Free trapped players quickly" }, { 15580, "Strike", 1, "Heal the tank through it" }, { 8269, "Enrage", 1, "Burn him at low health" } }, strategy = "A guard in the room with frost traps. For a tribute run, sneak past by using the frost trap trick. If fought, tank him and free players caught in ice." },
        [14324] = { abilities = { { 22884, "Psychic Scream", 32, "Fear ward the tank" }, { 17290, "Fireball", 4, "Interrupt this" }, { 15305, "Chain Lightning", 8, "Spread out a bit" }, { 15982, "Healing Wave", 8, "Interrupt the heal" }, { 22883, "Heal", 2, "Interrupt the heal" }, { 13745, "Arcane Explosion", 64, "Keep melee light near him" }, { 17194, "Mind Blast", 32, "Interrupt this" }, { 17139, "Power Word: Shield", 2, "Dispel the shield" } }, strategy = "Cho'Rush is a caster whose spell set can vary between runs. Interrupt heals and big casts, dispel his shields and keep fear protection on the tank. Kill him before or alongside King Gordok. Note this entry also covers the tribute chest." },
        [14325] = { abilities = { { 22860, "Call Reavers", 1, "Off-tank the reavers" }, { 22859, "Mortal Cleave", 1, "Face him away from melee" }, { 22857, "Retaliation", 1, "Stop melee during retaliation" }, { 19134, "Intimidating Shout", 1, "Tank uses fear immunity" }, { 8599, "Enrage", 1, "Save burst for enrage" } }, strategy = "Kromcrush calls in reaver adds, so assign an off-tank to them. Face him away from the group because of his cleave, and stop melee when retaliation is up. Warriors use Berserker Rage against his fear." },
        [14326] = { abilities = { { 15749, "Shield Charge", 1, "Tank stays close" }, { 11972, "Shield Bash", 1, "Casters watch for lockouts" }, { 10101, "Knock Away", 1, "Tank against a wall" }, { 15580, "Strike", 1, "Heal the tank through it" }, { 8269, "Enrage", 1, "Burn him at low health" } }, strategy = "An ogre guard with shield abilities. For a tribute run leave him alive. Otherwise tank him against a wall and burn him down, saving damage for his enrage." },
        [14327] = { abilities = { { 22709, "Void Bolt", 32, "Interrupt this", nil, { 3, 6 } }, { 17228, "Shadow Bolt Volley", 32, "Interrupt this", { 8, 13 }, { 13, 18 } }, { 13338, "Curse of Tongues", 32, "Remove from casters", { 9, 12 }, { 18, 22 } }, { 16247, "Curse of Thorns", 32, "Remove curse quickly", { 2, 9 }, { 15, 35 } }, { 12742, "Immolate", 4, "Dispel if possible", { 7, 12 }, { 25, 30 } } }, strategy = "Lethtendris is a shadow caster with an imp pet, so line-of-sight pull her to the tank. Rotate interrupts on Void Bolt and Shadow Bolt Volley. Decurse casters and kill or control the imp." },
        [14338] = { abilities = {  }, strategy = "Not a fight. Use a Gordok Shackle Key to free Knot and open his cache for loot and the Ogre Suit recipe." },
        [14354] = { abilities = { { 22424, "Blast Wave", 4, "Casters stay out of melee range", { 2, 10 }, { 10, 18 } }, { 15228, "Fireball", 4, "Interrupt when possible", { 1, 1 }, { 3, 3 } }, { 14145, "Fire Blast", 4, "Healers watch for burst damage", { 1, 4 }, { 8, 8 } } }, strategy = "Chase Pusillin through the wing until he stops to fight alongside his imps. Tank him and the imps together while DPS kills Pusillin first. He is a fragile caster, so interrupt his Fireballs and finish him quickly." },
        [14506] = { abilities = { { 23224, "Veil of Shadow", 32, "Dispel the curse quickly", { 11, 14 }, { 14, 20 } }, { 20989, "Sleep", 32, "Dispel sleeping players", { 9, 13 }, { 14, 17 } }, { 18670, "Knock Away", 1, "Tank against a wall", { 4, 9 }, { 9, 15 } }, { 22713, "Flame Buffet", 4, "Heal through stacks" }, { 17146, "Shadow Word: Pain", 32, "Dispel it", { 5, 9 }, { 22, 25 } }, { 16636, "Berserker Charge", 1, "Stay near the tank" } }, strategy = "Summoned during the warlock epic mount quest. Tank him against a wall and dispel sleep and shadow effects. Stack flame buffet healing on the tank and burn him before the stacks grow." },
        [14507] = { abilities = { { 23979, "Holy Wrath", 2, "Interrupt this" }, { 23861, "Poison Cloud", 8, "Move out of the cloud" }, { 23865, "Parasitic Serpent", 8, "Kill the snakes" }, { 23860, "Holy Fire", 4, "Interrupt this" }, { 23858, "Holy Nova", 2, "Melee stay spread" }, { 23862, "Venom Spit", 8, "Cure the poison" }, { 23895, "Renew", 2, "Dispel his renew" }, { 8269, "Enrage", 1, "Save burst for enrage" } }, strategy = "Venoxis starts as a troll priest with holy wrath and holy nova, so interrupt and dispel his renew. At half health he becomes a snake, leaving poison clouds that must be avoided. Cure poisons and kill any snakes." },
        [14509] = { abilities = { { 24173, "Resurrection", 2, "Kill all three together" }, { 22666, "Silence", 8, "Interrupt the adds", { 6, 18 }, { 6, 24 } }, { 22859, "Mortal Cleave", 1, "Face him away from melee", { 12, 24 }, { 12, 24 } }, { 8269, "Enrage", 1, "Save burst for enrage" } }, strategy = "Thekal and his two helpers must die close together or they revive. Balance damage so all three drop at the same time. In phase two he turns into a tiger, so tank him away from the raid." },
        [14510] = { abilities = { { 24099, "Poison Bolt Volley", 8, "Cure the poison" }, { 24083, "Hatch Eggs", 32, "Kill the spiders quickly" }, { 24300, "Drain Life", 32, "Interrupt this" }, { 24111, "Corrosive Poison", 8, "Cure the poison" }, { 22911, "Charge", 1, "Stay alert for charges" }, { 24109, "Enlarge", 64, "Kill the enlarged spider" }, { 3391, "Thrash", 1, "Heal the tank through it" } }, strategy = "Mar'li alternates between troll and spider form. In troll form, cure poison volleys and kill the spiders that hatch from eggs. In spider form she webs and charges players, so keep the tank ready to regain threat." },
        [14515] = { abilities = { { 24210, "Mark of Arlokk", 1, "Marked player stays near tank" }, { 12540, "Gouge", 1, "Off-tank picks up after gouge" }, { 15589, "Whirlwind", 1, "Melee step out of whirlwind" }, { 24212, "Shadow Word: Pain", 32, "Dispel it" }, { 24213, "Ravage", 1, "Heal through ravage" }, { 15582, "Backstab", 1, "Stay out of her back" }, { 26350, "Cleave", 1, "Face her away from melee" }, { 3391, "Thrash", 1, "Heal the tank through it" } }, strategy = "Arlokk marks a player and her panthers chase them. The marked player should stay near the tank. She vanishes and returns as a panther, so be ready to pick her back up." },
        [14516] = { abilities = { { 7645, "Dominate Mind", 32, "CC the controlled player", { 15, 17 }, { 30, 40 } }, { 17393, "Shadow Bolt", 32, "Interrupt if possible", { 7, 9 }, { 7, 9 } }, { 15284, "Cleave", 1, "Face him away from melee", { 3, 4 }, { 3, 6 } }, { 22644, "Blood Leech", 1, "Heal the tank through drains", { 10, 12 }, { 20, 25 } }, { 23261, "Summon Darkreaver's Fallen Charger", 1, "Kill the charger first" } }, strategy = "Summoned by the paladin charger quest. Tank him facing away so cleave only hits the tank, and kill his charger when it appears. Crowd control any mind controlled player and interrupt shadow bolts." },
        [14517] = { abilities = { { 23954, "Great Heal", 2, "Interrupt this" }, { 23970, "Throw Liquid Fire", 4, "Move out of the fire" }, { 6605, "Terrifying Screech", 32, "Tank uses fear immunity" }, { 23918, "Sonic Burst", 1, "Casters avoid stacking" }, { 16098, "Curse of Blood", 32, "Remove the curse" }, { 23919, "Swoop", 1, "Keep healthy, avoid stacking" }, { 23953, "Mind Flay", 32, "Interrupt this" }, { 23952, "Shadow Word: Pain", 32, "Dispel it" } }, strategy = "Jeklik starts in bat form, summoning bats and silencing players. At half health she turns troll and casts heals that must be interrupted, while bombing bats drop fire. Keep interrupts ready and move out of fire. Remove curses and shadow damage effects on the raid." },
        [14601] = { abilities = { { 23340, "Shadow of Ebonroc", 32, "Swap to the off tank immediately" }, { 22539, "Shadow Flame", 32, "Wear an Onyxia Scale Cloak" }, { 23339, "Wing Buffet", 1, "Re-establish threat after knockback" }, { 3391, "Thrash", 1, "Healers keep tank topped" } }, strategy = "Shadow of Ebonroc on a tank makes the boss heal from that player's attacks, so the other tank taunts right away until it fades. Everyone wears an Onyxia Scale Cloak for Shadow Flame. Keep the boss facing away from the raid and swap tanks as needed." },
        [14682] = { abilities = { { 16508, "Intimidating Roar", 1, "Tank regains threat after fear", { 5, 20 }, { 30, 60 } }, { 17745, "Diseased Spit", 8, "Cure disease if possible", { 0, 5 }, { 8, 16 } }, { 8269, "Enrage", 1, "Burn him fast when enraged" } }, strategy = "Sever is a seasonal elite who fears nearby enemies and spits disease. Cure the disease and be ready to recover threat after fears. Save cooldowns for when he enrages." },
        [14684] = { abilities = { { 8398, "Frostbolt Volley", 16, "Spread out and use frost resist", { 2, 16 }, { 8, 16 } }, { 16799, "Frostbolt", 16, "Interrupt this", { 2, 5 }, { 2, 5 } }, { 12096, "Fear", 32, "Fear ward or tremor totem" } }, strategy = "Balzaphon is a seasonal frost caster. Interrupt his Frostbolts and spread out to limit Frostbolt Volley damage. Bring fear protection for his Fear." },
        [14686] = { abilities = { { 16838, "Banshee Shriek", 32, "Use fear wards or tremor", { 0, 20 }, { 20, 20 } }, { 7645, "Dominate Mind", 32, "Crowd control charmed allies", { 10, 30 }, { 30, 60 } }, { 17105, "Banshee Curse", 32, "Remove the curse", { 0, 30 }, { 12, 30 } }, { 22743, "Ribbon of Souls", 32, "Heal through the damage", { 0, 25 }, { 5, 25 } } }, strategy = "Lady Falther'ess is a banshee who fears, curses and mind controls players. Remove curses, handle charmed players with stuns, and keep the tank near walls to reduce fear chaos. Focus her down quickly." },
        [14690] = { abilities = { { 14907, "Frost Nova", 16, "Melee free yourselves quickly", { 5, 33 }, { 33, 33 } }, { 15245, "Shadow Bolt Volley", 32, "Healers top off the group", { 5, 16 }, { 16, 16 } } }, strategy = "An undead caster using frost and shadow. Free melee quickly from frost nova and heal through shadow volleys. Burn him down as a group." },
        [14693] = { abilities = { { 22643, "Frostbolt Volley", 16, "Healer watches group health", { 0, 3 }, { 3, 10 } }, { 15531, "Frost Nova", 16, "Melee get out after nova", { 0, 5 }, { 12, 20 } }, { 17165, "Mind Flay", 32, "Interrupt this", { 0, 5 }, { 14, 40 } }, { 28873, "Lich Slap", 32, "Healer watches tank health", { 0, 5 }, { 17, 30 } } }, strategy = "Scorn is a seasonal lich who casts frost and shadow spells. Spread out and heal through Frostbolt Volley, and interrupt Mind Flay. Expect roots from Frost Nova, and keep the tank healed through his melee hits." },
        [14695] = { abilities = { { 20733, "Black Arrow", 32, "Heal through the shadow damage", { 2, 20 }, { 20, 20 } }, { 21390, "Multi-Shot", 64, "Spread out a bit", { 2, 10 }, { 10, 10 } }, { 7964, "Smoke Bomb", 1, "Move out of the smoke", { 2, 20 }, { 20, 20 } }, { 11972, "Shield Bash", 1, "Casters watch for lockouts", { 2, 10 }, { 5, 10 } }, { 16496, "Shoot", 1, "Stay close to limit ranged", { 3, 25 }, { 3, 25 } } }, strategy = "A summoned undead ranger who fights at range. Keep the tank close to him so he uses melee, and move out of smoke bombs. Casters should watch for shield bash lockouts." },
        [14834] = { abilities = { { 24324, "Blood Siphon", 32, "Get poisoned by the son first" }, { 24328, "Corrupted Blood", 32, "Stay spread out" }, { 24327, "Cause Insanity", 32, "CC the controlled player" }, { 24178, "Will of Hakkar", 64, "Heal through it" }, { 27680, "Berserk", 1, "Kill him before berserk" }, { 24321, "Poisonous Blood", 8, "Grab the poison" } }, strategy = "Hakkar drains life with blood siphon, and players need poison from the sons of Hakkar to survive it. Spread out to slow corrupted blood. Crowd control mind controlled players and burn him before berserk." },
        [14861] = { abilities = { { 22371, "Curse of Impotence", 32, "Remove the curse quickly", { 19, 19 }, { 4, 22 } }, { 12493, "Curse of Weakness", 32, "Remove the curse quickly", { 6, 18 }, { 3, 22 } }, { 3609, "Paralyzing Poison", 1, "Cure the poison", { 16, 19 }, { 27, 46 } } }, strategy = "A guardian at the Kirtonos balcony with curses and a paralyzing poison. Tank it in place while mages and druids remove curses and poisons get cured. Kill it quickly before moving to the herald." },
        [14887] = { abilities = {  }, strategy = "Ysondre, an Emerald Dragon, casts Lightning Wave, so spread out. She summons druid adds at intervals; kill them quickly. Face her away and keep melee at her sides." },
        [14888] = { abilities = {  }, strategy = "Lethon is one of the Emerald Dragons; he breathes noxious gas, sweeps his tail, and puts a Mark of Nature on dead players. He summons shades from the raid that heal him when they reach him, so kill them fast. Tank him facing away and keep melee at his sides." },
        [14889] = { abilities = {  }, strategy = "Emeriss, an Emerald Dragon, spawns mushrooms from dead players and inflicts a spreading disease. Spread out, cure disease quickly, and avoid the mushrooms. Tank her facing away and stay at her sides." },
        [14890] = { abilities = {  }, strategy = "Taerar, an Emerald Dragon, fears the raid and splits into shades at intervals. Tank the shades and kill them quickly before resuming on Taerar. Face him away and keep melee at his sides." },
        [15082] = { abilities = { { 24646, "Avatar", 1, "Kite away from him" }, { 6524, "Ground Tremor", 1, "Melee expect a stun", { 18, 20 }, { 18, 20 } }, { 24648, "Entangling Roots", 8, "Dispel the roots", { 10, 15 }, { 10, 15 } } }, strategy = "Gri'lek grows huge and chases a single target. Kite him when he does and dispel the roots on players. Heal through ground tremor stuns." },
        [15083] = { abilities = { { 24728, "Summon Nightmare Illusions", 1, "Kill illusions quickly" }, { 24664, "Sleep", 32, "Dispel sleeping players", { 12, 15 }, { 17, 33 } }, { 24684, "Chain Burn", 32, "Stay at range", { 20, 26 }, { 20, 26 } }, { 24685, "Earth Shock", 8, "Interrupt if possible", { 9, 15 }, { 9, 15 } } }, strategy = "Hazza'rah summons illusions that must be killed fast. Dispel sleep and keep healers ready for mana burn. Stay spread out." },
        [15084] = { abilities = {  }, strategy = "A rogue-like edge of madness boss. Tank him and expect him to vanish and gouge; have AoE ready when he reappears." },
        [15085] = { abilities = { { 24683, "Lightning Cloud", 8, "Move out of the cloud", { 12, 15 }, { 12, 15 } }, { 24680, "Chain Lightning", 8, "Spread out a bit", { 15, 19 }, { 15, 19 } }, { 24682, "Forked Lightning", 8, "Spread out a bit", { 7, 11 }, { 7, 11 } } }, strategy = "Wushoolay deals lightning damage. Nature resistance helps a lot. Spread out and move out of lightning clouds." },
        [15114] = { abilities = { { 22421, "Massive Geyser", 1, "Stay off the water" }, { 16099, "Frost Breath", 16, "Tank faces it away" }, { 24326, "Gahz'ranka Slam", 1, "Heal the tank through it" } }, strategy = "A fishing summon boss. Tank him facing away from the raid and avoid the geyser knockback. Heal through slams and keep everyone out of his frost breath." },
        [15263] = { abilities = {  }, strategy = "The Prophet Skeram mind controls players and splits into copies at certain health thresholds. Spread the tanks to cover all three platforms, kill the illusions fast, and control or crowd control mind controlled players. Keep interrupting and burning the real Skeram." },
        [15275] = { abilities = { { 7393, "Heal Brother", 8, "Keep the emperors far apart" }, { 568, "Arcane Burst", 64, "Move out of the arcane burst" }, { 26607, "Blizzard", 16, "Move out of the blizzard" }, { 26613, "Unbalancing Strike", 1, "Healers watch the tank" }, { 26007, "Uppercut", 1 }, { 802, "Mutate Bug", 8, "Kill mutated bugs quickly" }, { 804, "Explode Bug", 8, "Stay away from exploding bugs" }, { 26006, "Shadow Bolt", 32, "Use warlock tanks on Vek'lor" } }, strategy = "Vek'lor is immune to physical damage and Vek'nilash is immune to magic, so melee fight Vek'nilash and casters fight Vek'lor. Keep them apart so they cannot heal each other, and watch for teleport swaps where tanks must grab the new target. Avoid Blizzard and Arcane Burst, and kill the mutated bugs." },
        [15299] = { abilities = { { 25937, "Viscidus Freeze", 16, "Use frost damage to freeze him" }, { 25991, "Poison Bolt Volley", 8, "Cleanse poisons and heal through" }, { 25989, "Toxin", 8, "Move out of the toxin cloud" }, { 25993, "Poison Shock", 8, "Heal melee through the shock" }, { 25885, "Summon Globs of Viscidus", 1, "Kill globs before they rejoin" } }, strategy = "Viscidus must be hit with frost attacks to freeze him, then shattered with melee. He splits into many globs that must die before they reach him again. Bring frost wands and weapons, nature resistance and plenty of poison cleanses." },
        [15339] = { abilities = { { 25176, "Strength of Ossirian", 1, "Use the crystals to weaken him" }, { 25160, "Sand Storm", 1, "Avoid the sand tornadoes" }, { 25195, "Curse of Tongues", 32, "Decurse casters quickly" }, { 25188, "War Stomp", 1, "Melee be ready for the stun" } }, strategy = "Ossirian is very strong unless debuffed by the crystals around the room. Click a crystal to give him a weakness and switch damage types, moving him from crystal to crystal. Avoid tornadoes and decurse Curse of Tongues." },
        [15340] = { abilities = { { 25754, "Drain Mana", 32, "Mana users stay spread out" }, { 25684, "Summon Mana Fiends", 64, "Pick up and kill mana fiends" }, { 25672, "Arcane Eruption", 64, "Drain his mana before it fills" }, { 15550, "Trample", 1 } }, strategy = "Moam drains mana from the raid and casts Arcane Eruption when his mana is full. Hunters and warlocks drain his mana. When he turns to stone, kill the mana fiends that appear." },
        [15341] = { abilities = { { 25599, "Thundercrash", 8, "Tank re-establishes threat after", { 8, 8 }, { 22, 25 } }, { 6713, "Disarm", 1, nil, { 5, 5 }, { 15, 25 } }, { 8269, "Enrage", 1 } }, strategy = "General Rajaxx arrives after several waves of Qiraji adds, with NPC allies helping the raid. Rajaxx knocks back and drops threat with Thundercrash, so use multiple tanks. Keep healers back and kill his adds quickly." },
        [15348] = { abilities = { { 25646, "Mortal Wound", 1, "Swap tanks when stacks get high" }, { 26524, "Sand Trap", 1, "Step out of the sand trap" }, { 26527, "Enrage", 1, "Burn him below 30 percent" }, { 25814, "Wide Slash", 1, "Only the tank stands in front" } }, strategy = "Use two tanks to rotate Mortal Wound stacks. Move away from the sand traps that spawn under players. He enrages at 30 percent, so save cooldowns for that point." },
        [15369] = { abilities = { { 25749, "Stinger Spray", 8, "Heal through and spread out" }, { 25748, "Poison Stinger", 8, "Cleanse poisons quickly" }, { 25725, "Paralyze", 1, "Kill larvae before they reach players" }, { 8269, "Enrage", 1, "Burn him down fast" } }, strategy = "Ayamiss flies above the raid for the first phase, so ranged do most damage while melee kill the larvae. Kill larvae before they reach paralyzed players. Once he lands, tank him normally and burn him." },
        [15370] = { abilities = { { 96, "Dismember", 1, "Heal the bleeding target" }, { 1834, "Gathering Speed", 1, "Kite him while he chases" }, { 1557, "Full Speed", 1 }, { 19593, "Egg Explosion", 1, "Lure him onto the eggs" }, { 1881, "Summon Hive'Zara Hatchling", 1, "Kill hatchlings fast" } }, strategy = "Buru fixates on one player, who kites him around the room. Lead him next to eggs and break them to damage him, then kill the hatchlings that pop out. Below 20 percent he stops chasing and must be burned fast while healers handle heavy damage." },
        [15509] = { abilities = { { 26053, "Noxious Poison", 8, "Cleanse the poison quickly" }, { 26180, "Wyvern Sting", 8, "Do not dispel this" }, { 26050, "Acid Spit", 8, "Swap tanks as stacks grow" }, { 26051, "Frenzy", 1, "Hunters Tranquilizing Shot right away" }, { 26068, "Berserk", 1, "Burn her before berserk" } }, strategy = "Princess Huhuran calls for strong nature resistance across the raid. Hunters calm her Frenzy, healers cleanse poisons, and Wyvern Sting is left alone rather than dispelled. At 30 percent she berserks and hits much harder, so save cooldowns and burn her quickly." },
        [15510] = { abilities = { { 25646, "Mortal Wound", 1, "Swap tanks when stacks get high" }, { 518, "Summon Worm", 1, "Kill the worms before they enrage" }, { 720, "Entangle", 1, "Free entangled players fast" }, { 26662, "Berserk", 1 } }, strategy = "Fankriss stacks a healing reduction debuff on the tank, so two or three tanks rotate as stacks build. He summons Spawn of Fankriss that enrage over time, and these must be killed quickly. Kill any Vekniss Hatchlings that attack entangled players." },
        [15516] = { abilities = { { 26083, "Whirlwind", 1, "Melee back away during whirlwind" }, { 25174, "Sundering Cleave", 1, "Only the tank in front" }, { 26527, "Enrage", 1, "Burn her down quickly" }, { 27680, "Berserk", 1, "Finish her before the timer" }, { 19813, "Knockback", 1 } }, strategy = "Sartura and her three Sartura's Royal Guards whirlwind and hop between targets constantly. Stun-lock and kill the guards with tanks ready to pick them up, then focus Sartura. Melee back off during whirlwinds and ranged stay spread." },
        [15517] = { abilities = { { 26103, "Sweep", 1, "Melee step back from sweep" }, { 26102, "Sand Blast", 8, "Tank faces it away from raid" }, { 26616, "Boulder", 1, "Keep tanks in melee range" }, { 26093, "Quake", 8, "Move away from the dust cloud" }, { 26100, "Ground Rupture", 1, "Run from the ground rupture" }, { 26615, "Berserk", 1, "Burn him under 20 percent" } }, strategy = "Ouro alternates between above-ground and submerged phases. Keep melee tanks in range or he hurls boulders at the raid, and avoid his cleaving Sweep. When he submerges, run from the moving dust cloud and kill the scarabs." },
        [15543] = { abilities = { { 25786, "Toxic Vapors", 8, "Move out of the poison cloud" }, { 25812, "Toxic Volley", 8, "Cleanse poisons and heal through" }, { 19408, "Panic", 32, "Use Fear Ward and Tremor Totems" }, { 26561, "Berserker Charge", 1, "Healers watch the charge target" }, { 25807, "Great Heal", 2, "Interrupt Princess Yauj's heals" }, { 25790, "Vengeance", 8, "Expect stronger bugs after each death" }, { 18813, "Knock Away", 1, "Off tank ready to taunt" } }, strategy = "The Bug Trio are three bosses tanked separately: Lord Kri, Vem and Princess Yauj. Each death empowers the others, so many groups kill Yauj first while interrupting her heals, then Vem, with Kri last. Move out of the poison cloud Kri leaves behind and cleanse poison volleys." },
        [15727] = { abilities = { { 26029, "Dark Glare", 32, "Run with the beam to avoid it" }, { 26134, "Eye Beam", 8, "Spread out so it cannot chain" }, { 26143, "Mind Flay", 32, "Kill eye tentacles quickly" }, { 26220, "Digestive Acid", 8, "Leave the stomach before stacks grow" }, { 26235, "Cthun Vulnerable", 1, "Burn him while weakened" } }, strategy = "Phase one is the Eye of C'Thun; the raid stands spread in a large circle to stop Eye Beam chaining and runs ahead of the sweeping Dark Glare. Kill eye tentacles quickly. In phase two the raid kills Giant tentacles outside while a group inside the stomach kills the flesh tentacles, which makes C'Thun vulnerable." },
        [15928] = { abilities = { { 28089, "Polarity Shift", 8, "Move to your charge side" }, { 28167, "Chain Lightning", 8, "Spread out" }, { 28299, "Ball Lightning", 8, "Keep a melee near him" }, { 28337, "Magnetic Pull", 1, "Tanks ready after pull" }, { 28134, "Power Surge", 1 } }, strategy = "First kill Stalagg and Feugen on their platforms, tanks swapping when Magnetic Pull switches them. Thaddius then casts Polarity Shift, and players move to the side that matches their charge. Keep a melee near him to avoid Ball Lightning and spread to limit Chain Lightning." },
        [15931] = { abilities = { { 28169, "Mutating Injection", 1, "Run to the edge before it expires" }, { 28240, "Poison Cloud", 1, "Move out of the cloud" }, { 28157, "Slime Spray", 8, "Tank faces it away from raid" }, { 28137, "Slime Stream", 8, "Keep a tank in melee range" } }, strategy = "Mutating Injection makes players explode into poison clouds, so infected players run away from the raid. Tank him moving around the room. Kill slimes spawned by Slime Spray." },
        [15932] = { abilities = { { 28374, "Decimate", 8, "AoE the zombies after it lands" }, { 25646, "Mortal Wound", 1, "Swap tanks when stacks get high" }, { 29685, "Terrifying Roar", 1, "Use Fear Ward on tank" }, { 28371, "Frenzy", 1, "Hunters Tranquilizing Shot" } }, strategy = "Gluth eats zombies to heal himself, so a kiter keeps them away from him. Decimate drops everyone, zombies included, to low health, so AoE the zombies right after. Rotate tanks for Mortal Wound and keep Fear Ward on the tank." },
        [15936] = { abilities = { { 29371, "Eruption", 8, "Move with the safe zone" }, { 29998, "Decrepit Fever", 8, "Dispel the disease" }, { 29350, "Plague Cloud", 8, "Stay off the plagued floor" }, { 29310, "Mana Burn", 32, "Casters stay away from him" } }, strategy = "Heigan's room is split into strips that erupt in a repeating pattern, so the raid moves together into the safe strip. Periodically he teleports to his platform and the eruptions speed up, so everyone dances quickly through the pattern. Dispel the disease and keep mana users clear of his Mana Burn." },
        [15952] = { abilities = { { 28622, "Web Wrap", 8, "Ranged free wrapped players fast" }, { 29484, "Web Spray", 8, "Pre-shield tank before web spray" }, { 28776, "Necrotic Poison", 8, "Cleanse poison from tank" }, { 28741, "Poison Shock", 8, "Stand behind or beside her" }, { 28747, "Enrage", 1, "Burn her when she enrages" } }, strategy = "Maexxna wraps players on the wall, and ranged must free them quickly. Web Spray stuns everyone, so healers prepare the tank before it lands. Kill spiderlings and cleanse Necrotic Poison." },
        [15953] = { abilities = { { 28732, "Widow's Embrace", 64, "Use mind control to remove enrage" }, { 28796, "Poison Bolt Volley", 8, "Cleanse poisons and heal through" }, { 28794, "Rain of Fire", 4, "Move out of the fire" }, { 28798, "Enrage", 1, "Remove her enrage with worshippers" } }, strategy = "Faerlina enrages over time, which can only be removed by a mind controlled worshipper using Widow's Embrace. Priests handle mind control while tanks hold her worshippers and followers. Move out of Rain of Fire and cleanse poison." },
        [15954] = { abilities = { { 29213, "Curse of the Plaguebringer", 32, "Decurse the raid quickly" }, { 29212, "Cripple", 32, "Dispel the cripple" }, { 29208, "Blink", 8, "Tank re-establishes threat after blink" }, { 29247, "Summon Skeleton", 1, "Kill skeletons quickly" } }, strategy = "Noth blinks around and summons skeletons in waves, so tanks must pick them up fast. Decurse quickly. When he teleports to the balcony, kill the adds." },
        [15956] = { abilities = { { 28785, "Locust Swarm", 1, "Kite him away from the swarm" }, { 28783, "Impale", 1, "Stay off his line" }, { 28969, "Acid Spit", 8, "Heal through damage" }, { 28991, "Web", 8, "Kill adds quickly" }, { 26350, "Cleave", 1, "Only tanks stand in front" } }, strategy = "Tank Anub'Rekhan in one spot and kill Crypt Guards quickly. During Locust Swarm, the tank kites him around the room while everyone avoids him. Kill scarabs that spawn from corpses, and avoid his Impale." },
        [15989] = { abilities = { { 28522, "Icebolt", 16, "Spread out" }, { 29318, "Frost Breath", 16, "Hide behind ice blocks" }, { 28542, "Life Drain", 32, "Decurse quickly" }, { 28547, "Chill", 16, "Move out of blizzard" }, { 15847, "Tail Sweep", 1, "Stay out of tail" }, { 19983, "Cleave", 1, "Only tanks in front" }, { 28529, "Frost Aura", 1 } }, strategy = "Sapphiron needs frost resistance. In the air phase, Icebolt freezes players and Frost Breath kills anyone not behind an ice block. Decurse Life Drain and move out of blizzards." },
        [15990] = { abilities = { { 27808, "Frost Blast", 1, "Heal frozen players" }, { 28408, "Chains of Kel'Thuzad", 32, "Crowd control controlled players" }, { 27819, "Detonate Mana", 8, "Run out of the group" }, { 27810, "Shadow Fissure", 32, "Move out of the fissure" }, { 28478, "Frostbolt", 16, "Interrupt it" }, { 27812, "Void Blast", 32, "Move out of void blast" }, { 28467, "Mortal Wound", 1 } }, strategy = "Phase one is adds only. In phase two, Kel'Thuzad appears; interrupt Frostbolts, move out of fissures, spread for Detonate Mana. In phase three guardians come and must be tanked." },
        [16011] = { abilities = { { 29201, "Corrupted Mind", 32, "Rotate healers each minute" }, { 29204, "Inevitable Doom", 32, "Healers prepare for heavy damage" }, { 29865, "Poison Aura", 8, "Bring nature resistance" }, { 29232, "Fungal Bloom", 1, "Stand in spore clouds for crits" } }, strategy = "Loatheb prevents healing for most of the fight, allowing only a single heal per minute. Organize a healer rotation and use mushroom spores for crit bonus. Bring nature resistance and healthstones." },
        [16028] = { abilities = { { 28308, "Hateful Strike", 1, "Off tanks keep highest health" }, { 32309, "Slime Bolt", 8, "Heal through damage" }, { 28131, "Enrage", 1, "Burn him before he enrages" }, { 27680, "Berserk", 1 } }, strategy = "Patchwerk uses Hateful Strike on the melee target with the most health, so off tanks soak it. Healers focus on the tanks. Burn him before berserk." },
        [16042] = { abilities = { { 27382, "Shadow Bolt Volley", 32, "Burst him down at low health" }, { 27286, "Shadow Wrath", 32, "Healers watch the targeted player" }, { 27249, "Summon Spectral Assassin", 1, "Kill the assassins quickly" }, { 8269, "Enrage", 1, "Save cooldowns for the enrage" } }, strategy = "Lord Valthalak is a summoned shadow-themed boss. Kill or control his Spectral Assassins as they appear. His shadow damage ramps up near the end, so save cooldowns and burst him down fast at low health." },
        [16059] = { abilities = { { 19134, "Intimidating Shout", 1, "Fear ward or tremor the group" }, { 17138, "Flash Heal", 2, "Interrupt the heals" }, { 13323, "Polymorph", 1, "Dispel polymorphed players" }, { 17547, "Mortal Strike", 1, "Heal the tank through it" }, { 27673, "Five Fat Finger Exploding Heart Technique", 1 }, { 11314, "Fire Nova Totem", 4, "Destroy the totem fast" }, { 27618, "Blizzard", 16, "Move out of the blizzard" }, { 20902, "Aimed Shot", 1, "Healers watch the targeted player" } }, strategy = "Theldren is summoned in the Ring of Law for the tier 0.5 quest and brings a team of player-like adds. Use crowd control on several adds, then kill the healer first and work down from there. Interrupt heals, dispel polymorph, destroy totems quickly, and move out of ground area spells." },
        [16060] = { abilities = { { 28679, "Harvest Soul", 64, "Burn him down before it stacks" }, { 29317, "Shadow Bolt", 32, "Interrupt it" } }, strategy = "The raid splits into two halves: the living side and the dead side. Kill trainees on the living side; spirits appear on the dead side. When Gothik descends, burn him." },
        [16061] = { abilities = { { 29107, "Disrupting Shout", 1, "Stay out of range" }, { 26613, "Unbalancing Strike", 1, "Use students to tank" }, { 29125, "Hopeless", 1 } }, strategy = "Razuvious hits too hard for players to tank, so priests mind control Deathknight Understudies to tank him. Rotate mind controls and use the shield abilities. Keep mana users away from Disrupting Shout." },
        [16064] = { abilities = { { 28836, "Mark", 32, "Rotate tanks before marks stack" }, { 28863, "Void Zone", 32, "Move out of the void zone" }, { 28884, "Meteor", 4, "Split meteor with nearby players" }, { 28883, "Holy Wrath", 2, "Stay spread out" }, { 29061, "Shield Wall", 1 } }, strategy = "Four Horsemen must each be tanked in a corner, and tanks rotate between them as marks stack. Healers move between stations. Avoid void zones and spread for Holy Wrath." },
        [16080] = { abilities = { { 22271, "Arcane Explosion", 64, "Casters stay out of range" }, { 27564, "Reflection", 1, "Stop casting during reflection" }, { 27530, "Hurricane", 8, "Move out of the hurricane" }, { 27527, "Healing Touch", 8, "Interrupt this" }, { 27532, "Rejuvenation", 8, "Dispel the heal over time" }, { 27554, "Swipe", 1, "Only the tank stands in front" }, { 27737, "Moonfire", 64, "Dispel if possible" } }, strategy = "Mor Grayhoof is a summoned druid who shifts between several forms. In his faerie dragon form, stop casting into his reflect and step away from Arcane Explosion. Interrupt his heals and move out of Hurricane. Keep him faced away from the group in bear and cat form." },
        [16097] = { abilities = { { 27639, "Call Pet", 1, "Offtank or kill her pet" }, { 27636, "Starshards", 64, "Interrupt this", { 20, 30 }, { 20, 30 } }, { 27637, "Regrowth", 8, "Interrupt or dispel the heal", nil, { 20, 25 } }, { 14443, "Multi-Shot", 64, "Ranged spread out", { 0, 3 }, { 7, 12 } }, { 12024, "Net", 1, "Free netted players quickly", { 4, 9 }, { 12, 15 } } }, strategy = "Isalien is a summoned boss who fights alongside a beast pet. Offtank the pet away from the group while everyone else focuses Isalien. Interrupt her Starshards and heals, and keep ranged players spread to limit Multi-Shot damage." },
        [16118] = { abilities = { { 27688, "Bone Shield", 32, "Purge or burn through the shield" }, { 27696, "Summon Bone Mage", 32, "Kill bone mages fast" }, { 27690, "Summon Bone Minion", 32, "AoE the bone minions", { 10, 15 }, { 10, 15 } }, { 17228, "Shadow Bolt Volley", 32, "Healers top off the group", { 8, 10 }, { 8, 12 } }, { 8269, "Enrage", 1, "Save cooldowns for enrage" } }, strategy = "Kormok is summoned for the tier 0.5 quest. Kill the bone mages first and AoE the minions. Heal through shadow bolt volleys and save burst for when he enrages." },
    },
}
